/* kurs.js - содержание курса FPV «Взлёт» для игры: модули, задания, карточки, вопросы и тренажёры (уровни 1-2).
   Собрано из kurs-fpv-dannye.json (centrspektr/kursy, снимок 24.10.2026) скриптом mkkurs.py. Руками не править. */
window.KURS={"mods":[{"id":"m1","n":1,"t":"Старт и безопасность","sub":"Как устроен клуб, правила полётов, предполётная проверка","say":"Здесь ты узнаешь, что такое FPV, выучишь золотые правила безопасности и где можно летать. Научишься включать дрон по порядку, делать предполётную проверку и держать дрон на месте в симуляторе. В конце - первый полёт с тренером.","tasks":["m1_hello","m1_rules","m1_where","m1_fly","m1_power","m1_check","m1_day","m1_coach","m1_final"]},{"id":"m2","n":2,"t":"Устройство FPV-дрона","sub":"Из чего состоит дрон и как всё работает вместе","say":"Разберёшь дрон по частям: рама, моторы, мозг, камера и пульт. Поймёшь, как картинка попадает в очки, соберёшь дрон по системам и пролетишь плавный круг. На занятии назовёшь узлы на живом дроне.","tasks":["m2_frame","m2_brain","m2_video","m2_radio","m2_fly","m2_build","m2_rep","m2_coach","m2_final"]},{"id":"m3","n":3,"t":"Аккумуляторы","sub":"Банки, вольты, ёмкость, зарядка и хранение - на пальцах","say":"Узнаешь, что внутри аккумулятора, научишься считать вольты и читать наклейку. Поймёшь, когда пора садиться, как заряжать и хранить аккумулятор без опасности. Полетаешь в симуляторе и с тренером, следя за вольтами.","tasks":["akb_inside","akb_volt","fly_sim1","akb_count","akb_cap","fly_sim2","akb_label","akb_care","fly_mob","akb_rep","akb_final"]},{"id":"m4","n":4,"t":"Пилотирование","sub":"Стики, режимы полёта, трассы в симуляторе","say":"Поймёшь, что делает каждый стик и чем режим Angle отличается от Acro. Научишься тренировать руки, летать восьмёрку и проходить ворота. В конце - трасса на время и тест \"Пилот\".","tasks":["m4_sticks","m4_modes","m4_trainer","m4_moves","m4_fly8","m4_rep","m4_track","m4_coach","m4_final"]},{"id":"m5","n":5,"t":"FPV-гонки","sub":"Как устроены гонки, классы, правила и видеоканалы","say":"Узнаешь, как устроены гонки дронов: классы, правила, флаги и старт. Поймёшь, зачем каждому пилоту свой видеоканал и кто такие споттер и судья. Пролетишь мини-заезд в зале по сигналу.","tasks":["m5_race","m5_class","m5_fly1","m5_rules","m5_video","m5_roles","m5_fly2","m5_rep","m5_coach","m5_final"]},{"id":"m6","n":6,"t":"Ас","sub":"Зачётные трассы и разбор своих ошибок","say":"Будешь летать сложные трассы на время, разбирать свои ошибки по записи полёта и тренироваться как настоящий ас. В конце - экзамен Аса по всему курсу и зачётный заезд.","tasks":["m6_track","m6_fly1","m6_dvr","m6_fix","m6_fly2","m6_day","m6_as","m6_rep","m6_coach","m6_final"]}],"lib":{"m1_hello":{"t":"Добро пожаловать в курс FPV","sub":"Что такое FPV и как устроен курс","e":"👋","pts":10,"steps":[{"s":"cards","h":"Знакомимся","cards":[{"h":"FPV - полёт \"из кабины\"","p":"FPV - это когда ты видишь полёт глазами дрона. На дроне стоит камера, картинка летит в очки пилота. Ты как будто сидишь в кабине маленького самолёта.","pic":"ochki"},{"h":"С чего начинаем","p":"Сначала летаем в симуляторе на компьютере (Квадросим, Ворон): там аварии бесплатные. Потом - маленький Mobula 7 в зале с тренером. Он лёгкий, винты в защите, учиться на нём безопасно.","pic":"mob"},{"h":"Как устроен курс","p":"Курс - это модули. В модуле задания, в задании шаги: прочитай карточки, сыграй в тренажёр, ответь на вопросы. Шаги открываются сами по порядку. Следующий модуль открывает тренер, когда проверит твои задания.","pic":"chain:Модуль>Задания>Шаги"},{"h":"Ошибаться можно","p":"Ошибся в вопросе - сразу увидишь пояснение, почему так. Если набрал меньше 70%, появится доп. задание: те же темы, но другими словами. Очки за него не дают, зато тема точно запомнится.","pic":"e:💡"}]},{"s":"quiz","h":"Проверь себя","n":4,"pool":[["Что значит FPV?",["Полёт с видом из камеры дрона","Полёт только по прямой","Название пульта"],"FPV - вид от первого лица: пилот видит полёт через камеру дрона."],["Где новичок учится летать в первую очередь?",["В симуляторе на компьютере","Сразу на большом дроне на улице","Нигде, сразу на гонке"],"В симуляторе аварии ничего не стоят - там и набирают первые часы."],["Ты ошибся в вопросе. Что будет?",["Покажется пояснение, почему так","Курс закроется","Снимут все очки"],"Сразу покажется пояснение, а при слабом результате - доп. задание."],["Почему FPV-пилоту нужен помощник рядом?",["Пилот в очках не видит, что вокруг","Чтобы держать АКБ","Так требует симулятор"],"Пилот видит только картинку с камеры, а помощник видит дрон и людей вокруг."],["Когда появляется доп. задание?",["Если результат меньше 70%","Всегда после каждого шага","Только у тренера"],"Если результат ниже 70%, нужно повторить тему другими словами."]],"x":[["Как называется полёт, когда видишь глазами дрона?",["FPV","Автопилот","Таймлапс"],"Это FPV - вид от первого лица."],["Из чего состоит задание в курсе?",["Из шагов: карточки, тренажёр, вопросы","Только из одного теста","Из видео на час"],"Задание - это шаги: карточки, тренажёр, вопросы."]]}]},"m1_rules":{"t":"Золотые правила безопасности","sub":"5 правил, которые знает каждый пилот","e":"🛡","pts":20,"steps":[{"s":"cards","h":"5 золотых правил","cards":[{"h":"1. Летаем только с тренером","p":"На занятии запуск разрешает тренер. Он видит всю площадку и знает, кто где стоит. Свой дрон дома без взрослых не запускаем.","pic":"e:🧑‍🏫"},{"h":"2. Не над людьми","p":"Никогда не летаем над людьми и рядом с ними. Зрители стоят за сеткой или линией безопасности. Даже маленький дрон на скорости может поранить.","pic":"e:🚷"},{"h":"3. Рядом наблюдатель","p":"Пилот в очках видит только картинку с камеры. Наблюдатель (споттер) стоит рядом, смотрит на дрон и людей и сразу говорит: \"Стоп, человек!\"","pic":"e:👀"},{"h":"4. Что-то не так - дизарм","p":"Дизарм - это выключение моторов тумблером на пульте. Пропало видео, дрон летит не туда, кто-то вышел на площадку - сразу дизарм. Лучше уронить дрон, чем кого-то задеть.","pic":"e:🛑"},{"h":"5. После посадки","p":"Сел - сначала дизарм, потом подходим. Отключаем АКБ и только потом берём дрон в руки. К заармленному дрону не подходим и не ловим его руками.","pic":"e:✋"}]},{"s":"game","h":"Тренажёр: можно или нельзя?","g":"sort","tip":"опасно всё, где дрон рядом с людьми или моторы включены, когда к дрону подходят.","cats":["Можно","Нельзя"],"items":[["Взлететь, когда тренер сказал \"Можно\"",0,"Запуск на занятии разрешает тренер."],["Пролететь над головами зрителей",1,"Над людьми не летаем никогда."],["Подойти к дрону, пока моторы включены",1,"Сначала дизарм, потом подходим."],["Пропало видео - сразу дизарм",0,"Верно: без видео пилот слеп."],["Поймать летящий дрон рукой",1,"Винты режут кожу. Не ловим руками."],["Попросить друга быть наблюдателем",0,"Верно: наблюдатель видит то, чего не видит пилот."],["Встать зрителем за сеткой",0,"Верно: зрители за сеткой или линией."],["Запустить дрон дома в комнате без взрослых",1,"Летаем только с тренером или взрослым."],["Сначала дизарм, потом отключить АКБ, потом взять дрон",0,"Правильный порядок после посадки."],["Погоняться дроном за котом",1,"Животных не пугаем и не преследуем."]]},{"s":"quiz","h":"Проверь себя","n":5,"pool":[["Кто разрешает взлёт на занятии?",["Тренер","Любой пилот","Зрители"],"На занятии запуск всегда разрешает тренер."],["Где стоят зрители?",["За сеткой или линией безопасности","Под трассой","Рядом с пилотом в очках, вплотную к дрону"],"Зрители всегда за сеткой или линией безопасности."],["Что такое дизарм?",["Выключение моторов тумблером","Включение камеры","Зарядка АКБ"],"Дизарм - выключение моторов тумблером на пульте."],["Пропало видео в очках. Что делаешь?",["Сразу дизарм","Лечу дальше по памяти","Даю полный газ вверх"],"Без видео пилот ничего не видит - сразу дизарм."],["Дрон сел. Можно сразу брать его в руки?",["Нет, сначала дизарм и отключить АКБ","Да, сразу","Да, если он маленький"],"Сначала дизарм и отключить АКБ, потом берём."],["Кто такой наблюдатель (споттер)?",["Помощник, который смотрит на дрон и людей","Тот, кто снимает видео","Судья, который ставит очки"],"Он смотрит на дрон и людей, пока пилот в очках."],["Почему нельзя ловить дрон руками?",["Винты на скорости режут кожу","Дрон испачкается","Сломается пульт"],"Винты крутятся очень быстро и режут кожу даже у маленького дрона."],["Дрон летит не туда и не слушается. Лучшее решение?",["Дизарм, пусть падает","Пытаться догнать","Ждать, пока сядет АКБ"],"Дизарм: дрон упадёт, но никого не заденет. Дрон можно починить."],["Почему тумблер дизарма надо знать \"вслепую\"?",["В очках пульт не видно, а нажать надо мгновенно","Чтобы красиво выглядело","Его нельзя трогать"],"Пилот в очках не видит пульт, а действовать нужно за долю секунды."]],"x":[["К заармленному дрону...",["Не подходим","Подходим, если он стоит","Подходим сзади"],"Заармленный дрон может раскрутить винты в любой момент."],["Над кем можно летать?",["Ни над кем из людей","Над друзьями","Над тренером"],"Над людьми не летаем никогда."],["Человек вышел на площадку во время полёта. Действие?",["Сразу дизарм","Облететь его","Крикнуть и лететь дальше"],"Человек на площадке - сразу дизарм."],["Что делаем после посадки по порядку?",["Дизарм - отключить АКБ - взять дрон","Взять дрон - дизарм","Отключить пульт - взять дрон"],"Дизарм, отключить АКБ, только потом взять дрон."],["Почему наблюдатель важен, даже если пилот опытный?",["Пилот в очках не видит, что вокруг","Опытному не нужен","Чтобы хлопать"],"Любой пилот в очках не видит, что вокруг дрона."]]}]},"m1_where":{"t":"Где можно летать","sub":"Площадка, запретные места, законы и погода","e":"🗺","pts":20,"steps":[{"s":"cards","h":"Где летаем","cards":[{"h":"Наша площадка","p":"На занятиях летаем в зале или на площадке, которую выбрал тренер. Там сетка, ворота и понятные границы. Это лучшее место для учёбы.","pic":"e:🏟"},{"h":"Где летать нельзя","p":"Нельзя рядом с линиями электропередач, над дорогами, у аэропортов и вертолётных площадок, над чужими дворами и толпой людей. Дрон может врезаться, упасть на машину или помешать самолёту.","pic":"e:⚡🛣✈️"},{"h":"Есть законы","p":"В России есть правила для дронов. Во многих местах полёты запрещены, а в некоторых регионах запрет на всю территорию. Поэтому правило простое: летаем только там, где разрешил тренер.","pic":"e:📜"},{"h":"Погода","p":"Дождь, снег и сильный ветер - не летаем на улице. Вода может замкнуть электронику, ветер сносит маленький дрон. Мороз быстро сажает АКБ. Для учёбы есть зал и симулятор.","pic":"e:🌧💨"}]},{"s":"game","h":"Тренажёр: летим или нет?","g":"sort","tip":"опасно всё рядом с проводами, дорогами, самолётами, чужими людьми и в плохую погоду.","cats":["Летим","Не летим"],"items":[["Зал клуба, тренер рядом",0,"Лучшее место для учёбы."],["Под проводами ЛЭП",1,"Провода почти не видно в очках, а удар о них опасен."],["Над оживлённой дорогой",1,"Упавший дрон может вызвать аварию."],["Рядом с аэродромом",1,"Там летают самолёты и вертолёты с людьми."],["Над соседским двором с людьми",1,"Над людьми и чужими дворами не летаем."],["В симуляторе дома",0,"Да, симулятор - всегда можно."],["На улице в сильный дождь",1,"Вода замыкает электронику."],["На площадке, которую выбрал тренер, без людей вокруг",0,"Да, место разрешено и безопасно."],["Над толпой на празднике, чтобы снять видео",1,"Над толпой не летаем никогда."],["В сильный ветер на улице на Mobula 7",1,"Ветер сносит лёгкий дрон."]]},{"s":"quiz","h":"Проверь себя","n":5,"pool":[["Где лучше всего учиться летать?",["В зале или на площадке клуба с тренером","Во дворе у дома","Над дорогой"],"В зале или на площадке клуба с тренером."],["Почему нельзя летать у ЛЭП?",["Провода плохо видно, удар опасен","Там плохой интернет","Там скучно"],"Провода почти не видны в очках, а удар о них опасен."],["Почему нельзя летать у аэродрома?",["Там летают самолёты с людьми","Там громко","Там нет розеток"],"Там летают самолёты и вертолёты, в них люди."],["Идёт дождь. Летим на улице?",["Нет, вода замкнёт электронику","Да, дрону всё равно","Да, если быстро"],"Вода может замкнуть электронику дрона."],["Главное правило клуба про место полёта?",["Летаем там, где разрешил тренер","Где угодно, если нет людей","Только ночью"],"Летаем только там, где разрешил тренер."],["Какие дроны в России ставят на учёт?",["150 г и тяжелее","Любые, даже игрушечные","Только больше 100 кг"],"Сейчас на учёт ставят дроны от 150 г."],["Почему нельзя летать над чужим двором?",["Это чужая частная жизнь, и там люди","Двор слишком маленький","Можно, если не снимать"],"Это чужая частная жизнь, и там могут быть люди."],["Почему в сильный ветер на улице не летаем на маленьком дроне?",["Ветер сносит лёгкий дрон","Ветер мешает видео","Ветер разряжает пульт"],"Ветер сносит лёгкий дрон, и пилот теряет управление."]],"x":[["Над дорогой летать...",["Нельзя","Можно","Можно ночью"],"Упавший дрон может вызвать аварию."],["Сильный ветер на улице. Что выберешь?",["Зал или симулятор","Лететь на улице","Лететь выше"],"Ветер сносит лёгкий дрон - лучше зал или симулятор."],["Где можно летать всегда?",["В симуляторе","В парке","У школы"],"В симуляторе нет никаких рисков."],["Почему у больницы и над толпой нельзя?",["Дрон может упасть на людей","Там нет связи","Это скучно"],"Упавший дрон может ранить людей."]]}]},"m1_fly":{"t":"Полёт: висение на месте","sub":"Квадросим или Ворон: держим дрон в одной точке","e":"🎮","pts":15,"fly":true,"steps":[{"s":"cards","h":"Задание","cards":[{"h":"Летим в симуляторе","p":"Взлети в симуляторе и держи дрон в воздухе на месте 20 секунд, не касаясь земли. Потом мягко сядь. Запиши, сколько секунд получилось.","pic":"sim"},{"h":"Два стика","p":"Левый стик вверх-вниз - газ: вверх - дрон поднимается, вниз - опускается. Правый стик - наклоны: дрон летит туда, куда наклонил. В настройках симулятора выбери режим Angle: в нём дрон сам выравнивается, если отпустить правый стик. Газ держи плавно: маленькое движение стика - маленькое движение дрона. Дрон уплывает - поправь чуть-чуть в обратную сторону. Перед взлётом скажи \"Взлетаю!\", перед посадкой - \"Сажусь!\". Так делают на настоящих занятиях.","pic":"e:🕹"}]},{"s":"fly","h":"Впиши результат","rec":{"opts":["Квадросим","Ворон"],"ot":"Симулятор","v":"Сколько секунд продержался в воздухе","u":"с","ph":"например 20"}}]},"m1_power":{"t":"Включаем и выключаем по порядку","sub":"Пульт, очки, АКБ - и обратно","e":"🔌","pts":20,"steps":[{"s":"cards","h":"Порядок важен","cards":[{"h":"Включаем","p":"Сначала пульт, потом очки, и только потом подключаем АКБ к дрону. Так дрон сразу \"слышит\" пульт и показывает картинку.","pic":"chain:Пульт>Очки>АКБ"},{"h":"Выключаем - наоборот","p":"После посадки: дизарм, отключаем АКБ от дрона, потом выключаем очки и только потом пульт. Пульт выключаем последним, чтобы дрон до конца оставался под контролем.","pic":"chain:АКБ>Очки>Пульт"},{"h":"Перед подключением АКБ","p":"Проверь на пульте: тумблер арма выключен (дизарм), стик газа внизу. Если подключить АКБ при включённом арме, моторы могут сразу раскрутиться.","pic":"e:🎚"},{"h":"Говорим вслух","p":"Перед взлётом громко: \"Взлетаю!\", перед посадкой: \"Сажусь!\", если что-то не так: \"Дизарм!\". Все на площадке знают, что сейчас будет.","pic":"e:📣"}]},{"s":"game","h":"Тренажёр: что по порядку?","g":"order","sets":[{"q":"Включаем всё перед полётом","items":["Включить пульт","Включить очки","Подключить АКБ к дрону"],"why":"Пульт первым - дрон сразу его \"слышит\"."},{"q":"Выключаем после полёта","items":["Дизарм","Отключить АКБ от дрона","Выключить очки","Выключить пульт"],"why":"Пульт последним - дрон под контролем до конца."},{"q":"Взлёт","items":["Убедиться, что площадка свободна и тренер разрешил","Сказать \"Взлетаю!\"","Арм","Плавно дать газ"],"why":"Сначала разрешение и предупреждение, потом арм и газ."},{"q":"Посадка","items":["Сказать \"Сажусь!\"","Плавно убрать газ и сесть","Дизарм","Подойти и отключить АКБ"],"why":"К дрону подходим только после дизарма."}]},{"s":"quiz","h":"Проверь себя","n":5,"pool":[["Что включаем первым?",["Пульт","АКБ дрона","Очки"],"Пульт первым - тогда дрон сразу получит команды."],["Что выключаем последним?",["Пульт","АКБ","Очки"],"Пульт последним, чтобы дрон до конца был под контролем."],["Где должен быть стик газа, когда подключаешь АКБ?",["Внизу","Вверху","Посередине"],"Газ внизу - моторы не раскрутятся неожиданно."],["Что говорим перед взлётом?",["\"Взлетаю!\"","Ничего","\"Сажусь!\""],"Все на площадке должны знать, что дрон взлетает."],["Какое первое действие после посадки?",["Дизарм","Выключить пульт","Взять дрон"],"Дизарм - моторы заблокированы."],["Почему нельзя включать дрон без пульта?",["Дрон не получит команд с пульта","Сядет АКБ пульта","Очки сломаются"],"Приёмник не найдёт сигнал, дрон не получит команд."],["Почему перед подключением АКБ проверяют тумблер арма?",["Иначе моторы могут сразу раскрутиться","Чтобы светился диод","Это не нужно"],"При включённом арме моторы могут раскрутиться сразу."],["Ты выключил пульт, а АКБ дрона ещё подключена. Что плохого?",["Дрон остался без управления","Ничего","Пульт зарядится"],"Дрон остался без управления. Порядок: сначала АКБ, потом пульт."]],"x":[["Правильный порядок включения?",["Пульт - очки - АКБ","АКБ - пульт - очки","Очки - АКБ - пульт"],"Пульт - очки - АКБ."],["Правильный порядок выключения?",["АКБ - очки - пульт","Пульт - очки - АКБ","Как удобно"],"Наоборот: АКБ - очки - пульт."],["Что крикнуть, если надо срочно остановить моторы?",["\"Дизарм!\"","\"Ура!\"","Ничего"],"Все должны знать, что дрон сейчас упадёт."],["Почему газ должен быть внизу при подключении АКБ?",["Иначе моторы раскрутятся","Чтобы не сел пульт","Не важно"],"Иначе моторы могут сразу набрать обороты."]]}]},"m1_check":{"t":"Предполётная проверка","sub":"Дрон, АКБ, пульт, видео, площадка - за минуту","e":"✅","pts":20,"steps":[{"s":"cards","h":"Проверка за минуту","cards":[{"h":"1. Дрон","p":"Винты целые, без трещин, стоят правильно, крепко держатся. Рама и защита винтов без трещин. Ничего не болтается, провода не торчат к винтам.","pic":"mob"},{"h":"2. АКБ","p":"Не вздута, не помята, провода целые. Заряжена (проверяем тестером или после подключения - по вольтам в очках). Не горячая (комнатной температуры). Пухлую или повреждённую АКБ отдаём тренеру.","pic":"swell"},{"h":"3. Пульт и очки","p":"Пульт заряжен, тумблер арма в положении \"выключено\", газ внизу. Очки заряжены и стоят на своём канале (канал - своя \"волна\" видео, его даёт тренер).","pic":"e:🎮🥽"},{"h":"4. Видео","p":"После подключения АКБ в очках есть чёткая картинка с камеры. Нет картинки или шум - не летим, зовём тренера.","pic":"osd1"},{"h":"5. Площадка","p":"На площадке никого нет, зрители за сеткой, наблюдатель рядом, тренер разрешил. Только теперь: \"Взлетаю!\"","pic":"e:🏟"}]},{"s":"game","h":"Тренажёр: летим или не летим?","g":"sort","tip":"не летим, если что-то сломано, вздуто, не заряжено, нет картинки или на площадке люди.","cats":["Летим","Не летим"],"items":[["На винте трещина",1,"Треснувший винт может отломиться в полёте."],["АКБ немного вздулась",1,"Вздутая АКБ опасна, отдаём тренеру."],["В очках чёткая картинка, вольты в норме",0,"Всё готово."],["На площадке стоит человек",1,"Ждём, пока площадка освободится."],["Пульт заряжен, арм выключен, газ внизу",0,"Пульт готов."],["В очках нет картинки",1,"Без видео не летим."],["Тренер разрешил, зрители за сеткой",0,"Можно говорить \"Взлетаю!\""],["Провод торчит прямо к винту",1,"Винт перерубит провод."],["У тебя и соседа один и тот же видеоканал",1,"Картинки будут мешать друг другу."],["Взял АКБ, на которой только что летал",1,"Она разряжена и горячая: ставим остывать, берём заряженную."]]},{"s":"quiz","h":"Проверь себя","n":5,"pool":[["Что проверяем у винтов?",["Что целые, без трещин и держатся","Только цвет","Ничего"],"Винт должен быть целым, без трещин, и крепко держаться."],["АКБ вздулась. Что делаешь?",["Не летаю, отдаю тренеру","Летаю аккуратно","Прокалываю, чтобы сдулась"],"Вздутую АКБ не используем и отдаём тренеру."],["В очках нет картинки. Летим?",["Нет, зовём тренера","Да, по памяти","Да, если низко"],"Без картинки пилот слеп."],["Что последнее проверяем перед взлётом?",["Площадку и разрешение тренера","Цвет дрона","Погоду на завтра"],"Площадку: никого нет, тренер разрешил."],["В каком положении тумблер арма перед подключением АКБ?",["Выключен","Включён","Не важно"],"Выключен - моторы не раскрутятся."],["Почему у пилотов разные видеоканалы?",["Одинаковые каналы мешают друг другу","Для красоты","Так быстрее летает"],"Одинаковые каналы мешают друг другу, картинка в очках пропадает."],["Провод торчит к винту. Чем опасно?",["Винт перерубит провод","Ничем","Провод будет мешать камере"],"Винт перерубит провод, дрон может упасть или замкнуть."],["Зачем ждать, пока АКБ остынет?",["Горячая АКБ портится и может вздуться","Она тяжелее","Незачем"],"Горячая АКБ изнашивается и может вздуться."]],"x":[["Треснувший винт...",["Меняем до полёта","Пойдёт","Заклеиваем скотчем"],"Он может отломиться в полёте."],["Человек на площадке. Летим?",["Нет, ждём","Да, облетим","Да, если быстро"],"Ждём, пока площадка освободится."],["Сколько пунктов в предполётной проверке?",["5: дрон, АКБ, пульт и очки, видео, площадка","3: дрон, АКБ, пульт","7: дрон, АКБ, пульт, очки, видео, площадка, погода"],"Дрон, АКБ, пульт и очки, видео, площадка."]]}]},"m1_day":{"t":"День полётов: найди ошибки","sub":"История Пети на занятии","e":"📖","pts":15,"steps":[{"s":"game","h":"Найди ошибки Пети","g":"story","tip":"ошибки про порядок включения, людей рядом, дизарм и проверку перед полётом.","story":[["Петя пришёл на занятие и сначала включил пульт.",0,"Верно, пульт включаем первым."],["Он осмотрел винты и заменил один треснувший.",0,"Верно, с трещиной не летаем."],["Потом он подключил АКБ, не проверив, выключен ли арм.",1,"Перед АКБ проверяем: арм выключен, газ внизу."],["Петя полетел на том же канале, что и сосед.",1,"У каждого пилота свой видеоканал."],["Петя взлетел, ничего не сказав.",1,"Перед взлётом говорим \"Взлетаю!\""],["Попросил друга Колю быть наблюдателем.",0,"Верно, наблюдатель видит то, чего не видит пилот."],["Чтобы было красиво, Петя пролетел над зрителями.",1,"Над людьми не летаем никогда."],["Когда пропало видео, Петя сразу сделал дизарм.",0,"Верно, без видео - сразу дизарм."],["Во втором полёте Петя врезался в ворота и побежал к дрону, не сделав дизарм.",1,"Сначала дизарм, потом подходим."],["После посадки он сделал дизарм, отключил АКБ, потом выключил очки и пульт.",0,"Верно, пульт выключаем последним."]]},{"s":"quiz","h":"Коротко о главном","n":3,"pool":[["Какая ошибка Пети самая опасная для людей?",["Пролетел над зрителями","Не сказал \"Взлетаю!\"","Полетел на канале соседа"],"Полёт над людьми может закончиться травмой."],["Что Петя сделал правильно?",["Сделал дизарм, когда пропало видео","Взлетел молча","Побежал к дрону"],"Без видео пилот слеп - дизарм верное решение."],["Что Петя должен был сделать, прежде чем бежать к упавшему дрону?",["Дизарм","Выключить очки","Ничего, бежать быстрее"],"К дрону подходим только после дизарма."],["Что надо было сделать перед подключением АКБ?",["Проверить арм и газ","Включить музыку","Ничего"],"Проверить: арм выключен, газ внизу."]],"x":[["Что Петя забыл сказать перед взлётом?",["\"Взлетаю!\"","\"Привет!\"","Ничего не нужно"],"Говорим \"Взлетаю!\""],["Дрон упал. Первое действие?",["Дизарм","Бежать к дрону","Выключить очки"],"Сначала дизарм."]]}]},"m1_coach":{"t":"На занятии: покажи тренеру","sub":"Правила и проверка вживую","e":"🧑‍🏫","pts":20,"steps":[{"s":"cards","h":"Что будет на занятии","cards":[{"h":"Расскажи 5 правил","p":"Своими словами: летаем с тренером, не над людьми, наблюдатель рядом, что-то не так - дизарм, после посадки - дизарм и отключить АКБ.","pic":"e:🗣"},{"h":"Покажи проверку","p":"На Mobula 7 покажи предполётную проверку: винты, АКБ, пульт (арм выключен, газ внизу), очки, площадка. Покажи на пульте тумблер дизарма.","pic":"mob"}]},{"s":"coach","h":"Тренер принимает","p":"На занятии: рассказал 5 правил безопасности, показал предполётную проверку и тумблер дизарма на пульте. Тренер принимает."}]},"m1_final":{"t":"Итог модуля","sub":"Финальная проверка и первый полёт с тренером","e":"🎓","pts":30,"final":true,"steps":[{"s":"quiz","h":"Финальный тест: 10 вопросов","n":10,"pass":0.8,"from":["m1_rules","m1_where","m1_power","m1_check"],"xall":1},{"s":"coach","h":"Первый полёт","p":"На занятии, в режиме Angle и с тренером рядом: включил всё по порядку, сделал проверку, сказал \"Взлетаю!\", повисел на месте и сел, сказал \"Сажусь!\", сделал дизарм и выключил всё по порядку. Тренер принимает."}]},"m2_frame":{"t":"Рама, моторы и винты","sub":"Скелет и \"ноги\" дрона","e":"🛠","pts":20,"steps":[{"s":"cards","h":"Скелет и мышцы","cards":[{"h":"Рама - скелет","p":"Рама держит все детали. Её делают из карбона - лёгкого и очень прочного материала. У Mobula 7 рама пластиковая, с кольцами-защитой вокруг винтов.","pic":"e:🦴"},{"h":"Размер дрона","p":"Mobula 7 - это 75 мм: столько от одного мотора до противоположного по диагонали. Гоночный \"пятидюймовик\" - это дрон с винтами 5 дюймов (около 13 см).","pic":"e:📏"},{"h":"Моторы","p":"На каждом луче свой мотор, всего 4. Моторы бесколлекторные: внутри нет трущихся щёток, поэтому они мощные и долго работают.","pic":"e:🌀"},{"h":"Винты крутятся в разные стороны","p":"Соседние винты крутятся в разные стороны: два по часовой, два против. Иначе весь дрон начал бы крутиться вокруг себя.","pic":"quad"},{"h":"Винт - вращающееся крыло","p":"Лопасть винта похожа на маленькое крыло. Она отбрасывает воздух вниз, а дрон за счёт этого поднимается вверх. Чем быстрее крутится винт, тем сильнее тяга.","pic":"e:🪽"}]},{"s":"game","h":"Тренажёр: найди пару","g":"match","pairs":[["Рама","держит все детали"],["Мотор","крутит винт"],["Винт","гонит воздух вниз - тяга"],["Защита винтов","кольца вокруг винтов у вупа"],["Карбон","лёгкий и прочный материал рам"],["75 мм","размер Mobula 7 по диагонали"],["5 дюймов","размер винта гоночного дрона"],["Бесколлекторный","мотор без трущихся щёток"]]},{"s":"quiz","h":"Проверь себя","n":5,"pool":[["Что делает рама?",["Держит все детали","Снимает видео","Заряжает АКБ"],"Рама - скелет дрона, на ней держатся все детали."],["Сколько моторов у квадрокоптера?",["4","2","6"],"\"Квадро\" - четыре: по мотору на каждый луч."],["Почему соседние винты крутятся в разные стороны?",["Чтобы дрон не закручивало вокруг себя","Для красоты","Чтобы было тише"],"Иначе их закрутка вращала бы весь дрон вокруг себя."],["Из чего делают рамы гоночных дронов?",["Из карбона","Из дерева","Из стекла"],"Карбон лёгкий и очень прочный."],["Как винт поднимает дрон?",["Отбрасывает воздух вниз","Отталкивается от земли магнитом","Никак, поднимает АКБ"],"Винт отбрасывает воздух вниз, а воздух толкает дрон вверх."],["Что значит \"75 мм\" у Mobula 7?",["Расстояние между моторами по диагонали","Длина винта","Высота полёта"],"Это расстояние между осями противоположных моторов по диагонали."],["Что значит \"пятидюймовик\"?",["Дрон с винтами 5 дюймов","Дрон весом 5 кг","Дрон на 5 минут полёта"],"Это дрон с винтами 5 дюймов, около 13 см."],["Почему бесколлекторные моторы живут долго?",["Нет трущихся щёток","Они пластиковые","Их не включают"],"Внутри нет щёток, которые стираются."],["Винт поставили не той стороной. Что будет?",["Дрон не взлетит или перевернётся","Полетит быстрее","Ничего"],"Он погонит воздух вверх - дрон не взлетит или перевернётся."]],"x":[["Какая деталь держит все остальные?",["Рама","Камера","Антенна"],"Рама - скелет дрона."],["Если все 4 винта крутятся в одну сторону...",["Дрон закрутит вокруг себя","Он полетит быстрее","Ничего не изменится"],"Дрон начнёт крутиться вокруг себя."],["На что похожа лопасть винта?",["На маленькое крыло","На колесо","На парус"],"Лопасть - маленькое крыло, движущееся по кругу."],["Сколько примерно сантиметров в 5 дюймах?",["Около 13 см","5 см","50 см"],"1 дюйм = 2,54 см, 5 x 2,54 = около 13 см."]]}]},"m2_brain":{"t":"Мозг дрона","sub":"Полётный контроллер и регулятор","e":"🧠","pts":20,"steps":[{"s":"cards","h":"Кто командует","cards":[{"h":"Полётный контроллер - мозг","p":"Полётный контроллер - маленькая плата, мозг дрона. В нём есть датчик-гироскоп: он чувствует, куда дрон наклонился. Контроллер очень быстро поправляет моторы, и дрон держится ровно.","pic":"e:🧠"},{"h":"Регулятор - \"водитель\" моторов","p":"Регулятор (ESC) получает команду от контроллера и крутит каждый мотор так быстро, как велел контроллер. Без него мотор не закрутится.","pic":"e:⚙️"},{"h":"Путь команды","p":"Ты двигаешь стик - пульт отправляет сигнал - приёмник на дроне ловит его - контроллер решает, что сделать каждому мотору - регулятор крутит моторы. Всё это за доли секунды.","pic":"chain:Пульт>Приёмник>Контроллер>Регулятор>Мотор"}]},{"s":"game","h":"Тренажёр: путь команды","g":"order","sets":[{"q":"Ты сдвинул стик вперёд. По порядку, куда идёт команда?","items":["Пульт","Приёмник","Полётный контроллер","Регулятор","Мотор"],"why":"Пульт - приёмник - контроллер - регулятор - мотор."},{"q":"Как энергия идёт к мотору? Расставь по порядку","items":["АКБ","Регулятор","Мотор"],"why":"Ток идёт от АКБ через регулятор, который дозирует его для мотора."},{"q":"Дрон наклонился от ветра. Что происходит?","items":["Гироскоп чувствует наклон","Контроллер считает поправку","Регулятор меняет обороты","Дрон выравнивается"],"why":"Так дрон держится ровно сам, тысячи раз в секунду."},{"q":"Как сделать так, чтобы дрон полетел вперёд?","items":["Пилот наклоняет стик вперёд","Контроллер велит задним моторам крутиться быстрее","Дрон наклоняется носом вниз","Тяга толкает его вперёд"],"why":"Дрон летит туда, куда наклонён."}]},{"s":"quiz","h":"Проверь себя","n":5,"pool":[["Какая деталь - мозг дрона?",["Полётный контроллер","Винт","Рама"],"Полётный контроллер принимает решения за дрон."],["Что чувствует гироскоп?",["Наклоны и повороты дрона","Температуру","Свет"],"Гироскоп чувствует наклоны и повороты."],["Что делает регулятор (ESC)?",["Управляет скоростью моторов","Показывает видео","Заряжает АКБ"],"Регулятор крутит моторы так быстро, как велит контроллер."],["Кто получает команду с пульта первым на дроне?",["Приёмник","Мотор","Камера"],"Приёмник ловит сигнал пульта."],["Почему в режиме Angle дрон держится ровно, когда пилот отпустил стики?",["Контроллер сам поправляет моторы","Он висит на воздухе как шарик","Помогает ветер"],"Контроллер сам поправляет моторы, чувствуя наклоны гироскопом."],["Как часто контроллер поправляет моторы?",["Тысячи раз в секунду","Раз в минуту","Раз в секунду"],"Тысячи раз в секунду - человек так не может."],["Что такое \"4 в 1\"?",["Четыре регулятора на одной плате","Четыре АКБ","Четыре камеры"],"Четыре регулятора на одной плате - по одному на мотор."],["Что такое AIO?",["Контроллер и регулятор на одной плате","Режим полёта","Тип винта"],"All in one: контроллер и регуляторы на одной плате, как у Mobula 7."],["Чтобы лететь вперёд, дрон...",["Наклоняется носом вниз","Выключает передние моторы","Поднимается вверх"],"Дрон наклоняется носом вниз, и тяга толкает его вперёд."]],"x":[["Без какой детали мотор не закрутится?",["Без регулятора","Без камеры","Без антенны"],"Регулятор подаёт ток на мотор."],["Что идёт после приёмника на пути команды?",["Полётный контроллер","Пульт","Очки"],"Приёмник передаёт команду контроллеру."],["Порыв ветра наклонил дрон. Кто первым это заметил?",["Гироскоп","Пилот","Регулятор"],"Гироскоп в контроллере."]]}]},"m2_video":{"t":"Камера, видеопередатчик и очки","sub":"Как картинка попадает к пилоту","e":"📹","pts":20,"steps":[{"s":"cards","h":"Путь картинки","cards":[{"h":"Путь картинки","p":"Камера на носу дрона снимает. Видеопередатчик превращает картинку в радиосигнал. Антенна отправляет его в воздух. Антенна очков ловит, и пилот видит полёт.","pic":"chain:Камера>Видеопередатчик>Антенна>Очки"},{"h":"Каналы","p":"Видео летит на частоте 5,8 ГГц. Частоту делят на каналы, например R1 или F4. У каждого пилота свой канал, иначе картинки смешаются.","pic":"e:📻"},{"h":"Мощность","p":"Мощность видеопередатчика пишут в милливаттах (mW). В зале хватает 25 mW. Больше мощность - дальше сигнал, но сильнее мешаешь соседям.","pic":"e:📶"},{"h":"Аналог и цифра","p":"Бывает аналоговое видео (как старый телевизор: может рябить, но почти без задержки) и цифровое (чёткая картинка). Для гонок и учёбы часто берут аналог.","pic":"e:📺"},{"h":"Береги глаза","p":"В очках экран близко к глазам. После каждого полёта снимай очки и смотри вдаль. Закружилась голова - сними очки, сядь и отдохни.","pic":"e:😌"}]},{"s":"game","h":"Тренажёр: путь картинки","g":"order","sets":[{"q":"Как картинка попадает к пилоту?","items":["Камера","Видеопередатчик","Антенна дрона","Антенна очков","Очки пилота"],"why":"Камера - видеопередатчик - антенна - очки."},{"q":"Включаем видео перед полётом","items":["Включить очки","Выбрать свой канал","Подключить АКБ к дрону","Проверить картинку"],"why":"Канал выбираем заранее, чтобы не мешать соседям."},{"q":"После полёта - береги глаза","items":["Посадить дрон","Дизарм","Снять очки","Посмотреть вдаль"],"why":"Глазам нужен отдых после экрана вблизи."},{"q":"В очках рябь. Что проверить по порядку?","items":["Посадить дрон и сделать дизарм","Проверить, что в очках и на дроне твой канал","Проверить антенны на дроне и очках","Позвать тренера"],"why":"Сначала безопасность, потом канал и антенны - чаще всего виноваты они."}]},{"s":"quiz","h":"Проверь себя","n":5,"pool":[["Откуда пилот видит картинку?",["С камеры на дроне через очки","Со спутника","Из пульта"],"Камера на дроне снимает, картинка приходит в очки."],["Что делает видеопередатчик?",["Отправляет картинку в очки","Крутит моторы","Принимает команды пульта"],"Он превращает картинку в радиосигнал и отправляет в очки."],["Почему у пилотов разные каналы?",["Иначе картинки смешаются","Чтобы быстрее летать","Для красоты"],"На одном канале картинки смешиваются."],["Что делаем после полёта в очках?",["Снимаем и смотрим вдаль","Сразу следующий полёт без перерыва","Смотрим в телефон"],"Снимаем очки и смотрим вдаль - отдых для глаз."],["Какой мощности хватает в зале?",["25 mW","1000 mW","Чем больше, тем лучше"],"В зале хватает 25 mW, и соседи не мешают."],["На какой частоте обычно летит FPV-видео?",["5,8 ГГц","100 МГц","50 Гц"],"Около 5,8 ГГц."],["Что значит канал R1?",["Группа R, канал номер 1","Первый пилот","Скорость 1"],"Буква - группа каналов, цифра - номер в ней."],["Почему нельзя включать видеопередатчик без антенны?",["Он может перегреться и сгореть","Будет громко","Ничего страшного"],"Без антенны он может перегреться и сгореть."],["Чем плоха большая мощность в зале?",["Мешает соседям","Ничем","Дрон тяжелее"],"Сильный сигнал мешает соседним пилотам."]],"x":[["Что идёт после камеры на пути картинки?",["Видеопередатчик","Мотор","Приёмник"],"Видеопередатчик."],["Закружилась голова в очках. Что делаем?",["Снимаю очки и отдыхаю","Летаю дальше","Закрываю глаза в очках"],"Снимаем очки, садимся, отдыхаем."],["Двое пилотов на одном канале. Что будет?",["У обоих пропадёт или зарябит картинка","Будет в 2 раза чётче","Ничего"],"Картинки смешаются, у обоих рябь или пропадание."]]}]},"m2_radio":{"t":"Пульт и приёмник","sub":"Стики, привязка и failsafe","e":"🎮","pts":20,"steps":[{"s":"cards","h":"Управление","cards":[{"h":"Два стика - четыре движения","p":"Левый стик: от себя-на себя - газ (выше-ниже), влево-вправо - поворот на месте. Правый стик: от себя-на себя - наклон носом, влево-вправо - крен вбок. Это \"Mode 2\", так летает почти весь мир.","pic":"e:🕹"},{"h":"Приёмник","p":"На дроне стоит маленький приёмник с антенной. Он ловит сигнал только своего пульта и передаёт команды контроллеру.","pic":"e:📡"},{"h":"Привязка (бинд)","p":"Чтобы приёмник слушал только твой пульт, их \"знакомят\" - это называют бинд (привязка). Делается один раз, с тренером.","pic":"e:🔗"},{"h":"Failsafe - на случай потери связи","p":"Если связь с пультом пропала, дрон должен сам выключить моторы. Это failsafe (\"защита от сбоя\"). Тренер проверяет его перед полётами.","pic":"e:🛟"}]},{"s":"game","h":"Тренажёр: что делает стик","g":"match","pairs":[["Левый стик от себя","газ: дрон выше"],["Левый стик вбок","поворот на месте"],["Правый стик от себя","наклон носом, летит вперёд"],["Правый стик вбок","крен, летит вбок"],["Тумблер арма","включить или выключить моторы"],["Бинд","привязка приёмника к пульту"],["Приёмник","ловит сигнал пульта"],["Failsafe","что делать при потере связи"]]},{"s":"quiz","h":"Проверь себя","n":5,"pool":[["Какой стик отвечает за газ в Mode 2?",["Левый, вверх-вниз","Правый, вбок","Правый, вперёд-назад"],"Левый стик вверх-вниз - газ."],["Что делает правый стик вперёд?",["Наклоняет нос - дрон летит вперёд","Поднимает дрон выше","Включает моторы"],"Дрон наклоняется носом вниз и летит вперёд."],["Что делает приёмник?",["Ловит сигнал пульта","Отправляет видео","Заряжает АКБ"],"Приёмник ловит сигнал пульта и передаёт контроллеру."],["Связь с пультом пропала. Что должен сделать наш Mobula 7?",["Выключить моторы (failsafe)","Улететь домой сам","Лететь быстрее"],"Сработает failsafe: моторы выключатся, дрон упадёт и не улетит в людей."],["Почему пульт должен быть заряжен?",["Иначе пропадёт связь в полёте","Для подсветки","Это не важно"],"Пульт выключится - дрон потеряет связь."],["Что такое бинд?",["Привязка приёмника к пульту","Режим скорости","Название рамы"],"Привязка приёмника к одному пульту."],["Какая ось стиков не возвращается в центр сама?",["Газ","Крен","Тангаж"],"Стик газа держится там, где его оставили."],["Что такое рыскание (yaw)?",["Поворот на месте вокруг себя","Подъём вверх","Полёт вбок"],"Поворот дрона вокруг себя, как стрелка компаса."],["Почему для FPV-дрона failsafe обычно \"выключить моторы\"?",["Упасть на месте безопаснее, чем улететь","Так экономится АКБ","Это ошибка настройки"],"Падение на месте безопаснее, чем полёт без управления."]],"x":[["Левый стик влево-вправо делает...",["Поворот на месте","Полёт вверх","Полёт вперёд"],"Поворот на месте."],["Правый стик вбок делает...",["Полёт вбок (крен)","Газ","Дизарм"],"Крен: дрон наклоняется и летит вбок."],["Кто у нас делает привязку пульта?",["Тренер","Любой ученик","Она не нужна"],"Привязку делает тренер."]]}]},"m2_fly":{"t":"Полёт: круг вокруг точки","sub":"Квадросим или Ворон: плавный круг","e":"🎮","pts":15,"fly":true,"steps":[{"s":"cards","h":"Задание","cards":[{"h":"Летим в симуляторе","p":"Выбери в симуляторе предмет (дерево, ворота, столб) и облети вокруг него 3 круга, не задев. Запиши время.","pic":"sim"},{"h":"О чём думать","p":"Круг - это работа двух стиков сразу: правый ведёт вбок или вперёд, левый понемногу поворачивает. Держи газ ровно, чтобы не терять высоту. Это тренирует то, что ты узнал о стиках.","pic":"e:🕹"}]},{"s":"fly","h":"Впиши результат","sims":["Квадросим","Ворон"]}]},"m2_build":{"t":"Собери дрон по системам","sub":"Полёт, управление, видео, питание","e":"🧩","pts":20,"steps":[{"s":"cards","h":"4 системы дрона","cards":[{"h":"Полёт","p":"Рама, моторы, винты, регулятор. Всё, что держит дрон в воздухе.","pic":"e:🌀"},{"h":"Управление","p":"Пульт, приёмник, полётный контроллер с гироскопом. Всё, что решает, куда лететь.","pic":"e:🎮"},{"h":"Видео","p":"Камера, видеопередатчик, антенна, очки. Всё, что показывает пилоту полёт.","pic":"e:📹"},{"h":"Питание","p":"АКБ, разъём, провода питания. Всё, что даёт энергию. Подробно про АКБ - в модуле 3.","pic":"e:🔋"}]},{"s":"game","h":"Тренажёр: в какую систему?","g":"sort","tip":"Полёт держит в воздухе, Управление решает, Видео показывает, Питание даёт энергию.","cats":["Полёт","Управление","Видео","Питание"],"items":[["Мотор",0,"Мотор крутит винт - это полёт."],["Винт",0,"Винт создаёт тягу."],["Пульт",1,"Пульт - управление."],["Камера",2,"Камера - видео."],["АКБ",3,"АКБ - питание."],["Очки пилота",2,"Очки показывают картинку."],["Приёмник",1,"Приёмник ловит команды пульта."],["Видеопередатчик",2,"Отправляет картинку в очки."],["Регулятор",0,"Крутит моторы - полёт."],["Гироскоп",1,"Помогает контроллеру держать дрон ровно."],["Разъём АКБ",3,"Через него идёт питание."]]},{"s":"quiz","h":"Проверь себя","n":5,"pool":[["К какой системе относится камера?",["Видео","Питание","Полёт"],"Камера снимает картинку - это видео."],["К какой системе относится приёмник?",["Управление","Видео","Питание"],"Приёмник ловит команды - это управление."],["Что будет, если отказал видеопередатчик?",["Пропадёт картинка в очках","Перестанут крутиться моторы","Выключится пульт"],"Пропадёт картинка в очках, а управление останется."],["Без какой системы дрон вообще не включится?",["Питание","Видео","Ни без какой"],"Без питания энергии нет совсем."],["Какая система показывает пилоту, куда летит дрон?",["Видео","Питание","Полёт"],"Камера, видеопередатчик и очки - это видео."],["Отказал приёмник. Что будет?",["Команды не дойдут, сработает failsafe","Пропадёт картинка","Ничего"],"Команды не дойдут, сработает failsafe."],["Куда отнести регулятор?",["Полёт","Видео","Управление"],"Регулятор крутит моторы - система полёта."]],"x":[["Мотор относится к системе...",["Полёт","Питание","Видео"],"Мотор крутит винт."],["Очки относятся к системе...",["Видео","Управление","Полёт"],"Очки показывают картинку."],["Гироскоп относится к системе...",["Управление","Видео","Питание"],"Гироскоп помогает контроллеру держать дрон ровно."]]}]},"m2_rep":{"t":"Повторение: безопасность","sub":"История Маши и вопросы с другой стороны","e":"🔁","pts":15,"steps":[{"s":"game","h":"Найди ошибки Маши","g":"story","tip":"вспомни порядок включения, правила площадки и предполётную проверку.","story":[["Маша сначала подключила АКБ к дрону, а потом включила пульт и очки.",1,"Сначала пульт, потом очки, и только потом АКБ."],["Она проверила, что арм выключен и газ внизу.",0,"Верно."],["Маша взяла канал R1, хотя на нём уже летал Дима.",1,"У каждого пилота свой канал."],["Перед взлётом она громко сказала \"Взлетаю!\"",0,"Верно, все знают о взлёте."],["Видеопередатчик она включила без антенны, \"на минутку\".",1,"Без антенны видеопередатчик может сгореть."],["Когда дрон полетел не туда, Маша сразу сделала дизарм.",0,"Верно, лучше уронить дрон."],["Маша полетела во двор над соседями, потому что в зале было занято.",1,"Летаем только там, где разрешил тренер."],["После посадки Маша сделала дизарм и отключила АКБ.",0,"Верно."],["Она целый час меняла АКБ и летала снова, ни разу не сняв очки.",1,"После каждого полёта даём глазам отдых."]]},{"s":"quiz","h":"Вспомни модуль 1 по-новому","n":5,"pool":[["Ты наблюдатель. Видишь, что к трассе идёт человек. Что делаешь?",["Сразу говорю пилоту \"Стоп, человек!\"","Молчу, пилот сам увидит","Снимаю на телефон"],"Наблюдатель сразу говорит пилоту, пилот делает дизарм."],["Друг предлагает полетать над школьным стадионом во время матча. Ответ?",["Нет: там люди, а место не разрешено","Да, сверху красиво","Да, если низко"],"Над людьми не летаем, место должен разрешить тренер."],["Пульт выключился сам в полёте. Какое правило подготовки нарушено?",["Не проверили заряд пульта","Не сказали \"Взлетаю!\"","Никакое"],"Пульт должен быть заряжен - это часть предполётной проверки."],["Твоя АКБ после полёта горячая, а очередь снова твоя. Что делаешь?",["Беру другую, эта остывает","Лечу на горячей","Кладу её на батарею"],"Горячую АКБ ставим остывать, летим на другой."],["Ты собираешься взлетать, а наблюдателя нет. Что делаешь?",["Прошу кого-то быть наблюдателем","Взлетаю сам","Смотрю одним глазом из-под очков"],"Без наблюдателя пилот в очках не видит, что вокруг."],["Почему пульт включают раньше АКБ дрона? Подумай о приёмнике.",["Приёмник сразу найдёт пульт","Чтобы пульт нагрелся","Без разницы"],"Приёмник при включении сразу найдёт сигнал пульта."],["Почему нельзя ловить дрон, даже если моторы \"почти остановились\"?",["Без дизарма они могут раскрутиться в любой момент","Можно, если медленно","Можно в перчатке"],"Пока не сделан дизарм, моторы могут раскрутиться в любой момент."]],"x":[["Ты пилот, наблюдатель крикнул \"Стоп!\". Действие?",["Дизарм","Лечу дальше","Спрашиваю, что случилось"],"Сразу дизарм."],["Что общего у правил \"свой канал\" и \"не над людьми\"?",["Оба защищают от аварии","Ничего","Оба про скорость"],"Оба про то, чтобы никто не пострадал, если что-то пойдёт не так."]]}]},"m2_coach":{"t":"На занятии: назови узлы","sub":"На живом дроне, АКБ отключена","e":"🧑‍🏫","pts":20,"steps":[{"s":"cards","h":"Что будет на занятии","cards":[{"h":"Покажи на дроне","p":"АКБ отключена. Покажи и назови: раму, моторы, винты (какой куда крутится), плату контроллера, камеру, антенну видеопередатчика, приёмник, разъём АКБ.","pic":"mob"},{"h":"Расскажи путь","p":"Расскажи путь команды (пульт - приёмник - контроллер - регулятор - мотор) и путь картинки (камера - видеопередатчик - антенна - очки).","pic":"e:🗣"}]},{"s":"coach","h":"Тренер принимает","p":"На занятии: на дроне с отключённой АКБ назвал узлы и рассказал путь команды и картинки. Тренер принимает."}]},"m2_final":{"t":"Итог модуля","sub":"Финальная проверка и круг вживую","e":"🎓","pts":30,"final":true,"steps":[{"s":"quiz","h":"Финальный тест: 10 вопросов","n":10,"pass":0.8,"from":["m2_frame","m2_brain","m2_video","m2_radio"],"xall":1},{"s":"coach","h":"Круг на Mobula 7","p":"На занятии: облетел вокруг точки на Mobula 7 вживую, на ровной высоте, с наблюдателем, всё включил и выключил по порядку. Тренер принимает."}]},"akb_inside":{"t":"АКБ на пальцах","sub":"Что внутри и почему банки ставят \"этажами\"","e":"🔋","pts":20,"steps":[{"s":"cards","h":"Как устроен аккумулятор","cards":[{"h":"Банка - это маленький бак с энергией","p":"Аккумулятор дрона собран из одинаковых \"банок\" (ячеек). Каждая банка хранит энергию, как бак хранит топливо. Зарядили - бак полный, полетали - бак пустеет.","pic":"tank"},{"h":"Внутри - тонкие слои","p":"В банке свёрнуты тонкие слои, как блинчики в рулете. Между ними разделитель. Если банку проколоть или сильно ударить, слои соприкоснутся - замыкание, сильный нагрев и огонь. Поэтому с АКБ обращаемся бережно.","pic":"cell"},{"h":"Банки \"этажами\" - вольты складываются","p":"Одна банка даёт около 3,7 В. Если соединить банки друг за другом (последовательно), их вольты складываются, как этажи дома. 4 этажа = 4S = около 14,8 В. Буква S - сколько банок стоит \"этажами\".","pic":"stack"},{"h":"Почему на картинке \"столбиком\" и \"в ряд\"","p":"В тренажёре банки \"этажами\" нарисованы столбиком, а \"рядом\" - в ряд. Это просто картинка, чтобы было легко запомнить: столбик растёт вверх - растут вольты, ряд растёт вширь - растёт бак. В настоящей АКБ банки могут лежать как угодно, важно только, как соединены провода.","pic":"sp"},{"h":"Банки \"рядом\" - бак больше","p":"Если поставить банки рядом (параллельно), вольты не растут, зато бак становится больше - летаем дольше. Это буква P. В гоночных дронах чаще всего просто S: 1S, 4S, 6S.","pic":"par"},{"h":"Маленький Mobula 7 и большие дроны","p":"Mobula 7 обычно летает на одной банке (1S) - посмотри на наклейку своей АКБ. У больших 5-дюймовых гоночных дронов обычно 4S или 6S. Чем больше банок, тем мощнее дрон, но у каждого дрона своё число банок, другое ставить нельзя.","pic":"mob"}]},{"s":"game","h":"Тренажёр: собери АКБ из банок","g":"build"},{"s":"quiz","h":"Проверь себя","n":5,"pool":[["Из чего собран аккумулятор дрона?",["Из одинаковых банок (ячеек)","Из одной большой батарейки","Из конденсаторов"],"АКБ - это несколько одинаковых банок, соединённых вместе."],["Что означает буква S в \"4S\"?",["Сколько банок стоит \"этажами\" (последовательно)","Сколько банок стоит \"рядом\" (параллельно)","Сколько минут длится полёт"],"S - сколько банок стоит \"этажами\", то есть последовательно."],["Что происходит с вольтами, если банки поставить \"этажами\"?",["Складываются","Не меняются","Делятся пополам"],"Как этажи дома: каждый этаж добавляет свои 3,7 В."],["Сколько примерно вольт даёт одна обычная банка?",["Около 3,7 В","Около 1,5 В","Около 12 В"],"Номинал одной банки LiPo - 3,7 В. Это число пишут на наклейке."],["Почему нельзя прокалывать или бить АКБ?",["Слои внутри соприкоснутся - замыкание, нагрев и огонь","Она станет легче","Ничего не будет"],"Тонкие слои внутри соприкоснутся - будет замыкание, сильный нагрев и огонь."],["Что даёт параллельное соединение банок (буква P)?",["Бак больше - летаем дольше","Вольты складываются","Дрон становится легче"],"Банки рядом - вольты те же, а энергии больше, значит полёт дольше."],["У какой АКБ выше напряжение?",["6S","4S","1S"],"Чем больше банок \"этажами\", тем выше напряжение: 6 x 3,7 = 22,2 В."],["Сколько всего банок в АКБ 4S2P?",["8","6","4"],"4 \"этажа\", на каждом 2 банки рядом: 4 x 2 = 8."],["Какое номинальное напряжение у АКБ 3S?",["11,1 В","3,7 В","12,6 В"],"3 банки этажами: 3 x 3,7 = 11,1 В."],["Ты поставил 2 одинаковые банки рядом (2P). Что изменилось по сравнению с одной банкой?",["Ёмкость выросла в 2 раза, вольты те же","Вольты выросли в 2 раза","Ничего"],"Вольты те же 3,7 В, а ёмкость стала в 2 раза больше."]],"x":[["Петя соединил 3 банки \"этажами\". Как это записать?",["3S","3P","1S"],"\"Этажами\" = последовательно = буква S. 3 банки - 3S."],["Дом в 4 этажа - это сколько банок \"этажами\"?",["4S","1S","2P"],"Каждый этаж - одна банка последовательно: 4S."],["Ты поставил банки рядом, а не \"этажами\". Что изменилось?",["Ёмкость стала больше, вольты те же","Вольты выросли","Ничего"],"Рядом = параллельно: вольты не растут, растёт бак."],["Банку уронили и она помялась. Как правильно?",["Не использовать, показать тренеру","Поставить на зарядку","Выпрямить руками"],"Повреждённая банка может загореться. Её нельзя заряжать и использовать."],["Какая из записей значит \"6 банок последовательно\"?",["6S","6P","6C"],"Последовательно - буква S."],["Сколько вольт у АКБ 2S2P (номинал)?",["7,4 В","14,8 В","3,7 В"],"Вольты считаем только по \"этажам\": 2 x 3,7 = 7,4 В."]]}]},"akb_volt":{"t":"Вольты одной банки","sub":"Когда лететь, когда садиться, когда опасно","e":"🚦","pts":20,"steps":[{"s":"cards","h":"Главные числа банки","cards":[{"h":"4,2 В - бак полный","p":"Полностью заряженная обычная банка (LiPo) показывает 4,2 В. Больше заряжать нельзя.","pic":"scale"},{"h":"3,7 В - \"обычное\" число","p":"Это число пишут на наклейке (номинал). Банка в середине пути: ещё летаем.","pic":"scale"},{"h":"3,5 В - пора садиться","p":"Когда во время спокойного полёта банка показывает около 3,5 В, разворачиваемся и садимся. Лучше вернуться с запасом, чем упасть.","pic":"scale"},{"h":"Ниже 3,3 В - вредно","p":"Если разрядить банку сильнее, она портится: хуже держит заряд и может вздуться.","pic":"scale"},{"h":"3,8 В - для хранения","p":"Если не летаем несколько дней, оставляем банку около 3,8 В. Так она живёт дольше.","pic":"scale"},{"h":"LiPo и LiHV: в чём разница","p":"LiPo - обычная банка: полная 4,2 В. LiHV - банка \"с запасом\" (HV - высокое напряжение): полная 4,35 В, в ней чуть больше энергии. Такие часто стоят в маленьких дронах, как Mobula 7. Главное: каждую заряжаем в своём режиме зарядки. Тип написан на наклейке.","pic":"hv"}]},{"s":"game","h":"Тренажёр-светофор: лететь или садиться?","g":"light"},{"s":"quiz","h":"Проверь себя","n":5,"pool":[["Сколько вольт у полностью заряженной обычной банки LiPo?",["4,2 В","3,7 В","5 В"],"Полная банка LiPo - 4,2 В. Выше заряжать опасно."],["При каком напряжении на банку пора садиться?",["Около 3,5 В","4,1 В","3,9 В"],"Около 3,5 В на банку в спокойном полёте - пора на посадку."],["Какое напряжение банки подходит для хранения?",["Около 3,8 В","4,2 В","3,0 В"],"Около 3,8 В на банку - так АКБ меньше всего стареет."],["До скольких вольт можно заряжать банку LiHV?",["4,35 В","4,2 В","5 В"],"LiHV - \"высокое напряжение\": полная банка 4,35 В."],["Что будет, если часто разряжать банку ниже 3,3 В?",["Она испортится и может вздуться","Она станет мощнее","Ничего"],"Глубокий разряд портит банку: она теряет ёмкость и может вздуться."],["Что значит число 3,7 В на наклейке?",["Номинал: \"обычное\" напряжение банки","Полный заряд","Когда садиться"],"Это номинал - \"среднее\" напряжение банки, не полный заряд."],["Ты не будешь летать неделю. Что сделать с АКБ?",["Довести до 3,8 В на банку (режим хранения)","Зарядить до полной","Разрядить до нуля"],"Для хранения доводим до 3,8 В на банку: и не полная, и не пустая."],["Можно ли заряжать обычную LiPo в режиме LiHV до 4,35 В?",["Нет, только до 4,2 В в режиме LiPo","Да, так даже лучше","Да, если быстро"],"Обычную LiPo заряжаем только до 4,2 В, перезаряд опасен."],["Ты сел при 3,5 В, а через минуту АКБ показывает 3,7 В. Почему?",["Банка отдохнула без нагрузки - это нормально","Она сама зарядилась","Сломался датчик"],"Без нагрузки напряжение немного поднимается - банка \"отдыхает\". Это нормально."],["Почему лучше садиться с запасом, а не \"до последнего\"?",["На газу вольты проседают, дрон может упасть","Чтобы быстрее зарядить","Так требует закон"],"На газу вольты проседают сильнее, и дрон может отключиться в воздухе."]],"x":[["В очках пишет 3,5 В на банку. Твоё действие?",["Разворачиваюсь и сажусь","Делаю ещё 5 кругов","Даю полный газ"],"3,5 В на банку - сигнал садиться."],["Банка после зарядки показывает 4,2 В. Это...",["Полный бак","Половина","Опасно мало"],"4,2 В - полный бак обычной LiPo."],["Друг хранит АКБ полностью заряженными месяц. Что посоветуешь?",["Перевести в хранение около 3,8 В","Так и надо","Разрядить в ноль"],"Полные АКБ при хранении быстрее стареют. Для хранения - около 3,8 В."],["Что значат буквы HV в LiHV?",["Высокое напряжение - заряжается до 4,35 В","Тяжёлая версия","Для холодной погоды"],"HV - High Voltage, высокое напряжение: заряжается до 4,35 В."],["АКБ показывает 3,2 В на банку. Что с ней?",["Переразряжена - сказать тренеру","Всё нормально, можно летать","Она полная"],"Ниже 3,3 В - переразряд. Сразу сообщи тренеру, такую АКБ заряжают осторожно."]]}]},"fly_sim1":{"t":"Полёт: следим за временем","sub":"Квадросим или Ворон: чистые круги","e":"🎮","pts":15,"fly":true,"steps":[{"s":"cards","h":"Задание","cards":[{"h":"Летим в симуляторе","p":"Выбери любую трассу в Квадросиме или Вороне. Пролети 3 круга без аварий. Запиши лучшее время круга.","pic":"sim"},{"h":"Думай как с настоящей АКБ","p":"Представь, что у тебя 4S. Перед вылетом скажи себе: сажусь, когда будет 14 В (3,5 В на банку). Хороший пилот следит за АКБ, даже когда летит быстро.","pic":"scale"}]},{"s":"fly","h":"Впиши результат","sims":["Квадросим","Ворон"]}]},"akb_count":{"t":"Считаем всю АКБ","sub":"Вольты банки x количество банок","e":"🧮","pts":20,"steps":[{"s":"cards","h":"Простое правило","cards":[{"h":"Вся АКБ = банка x S","p":"Чтобы узнать напряжение всей АКБ, умножь вольты одной банки на число банок. 4S полная: 4 x 4,2 = 16,8 В. 4S \"пора садиться\": 4 x 3,5 = 14 В.","pic":"stack"},{"h":"В очках часто видно всю АКБ","p":"Дрон показывает в очках напряжение всей АКБ. Чтобы понять, сколько на одну банку, раздели: 14,8 В : 4 = 3,7 В на банку.","pic":"osd"}]},{"s":"game","h":"Тренажёр: посчитай вольты","g":"calc","n":6}]},"akb_cap":{"t":"Ёмкость и токоотдача","sub":"mAh - размер бака, C - ширина шланга","e":"⛽","pts":20,"steps":[{"s":"cards","h":"Три главных буквы","cards":[{"h":"mAh - размер бака","p":"Ёмкость пишут в миллиампер-часах: 450 mAh, 1500 mAh. Чем больше число, тем больше энергии и тем дольше полёт. Но и АКБ тяжелее.","pic":"tank"},{"h":"C - ширина шланга","p":"Число C (например, 100C) показывает, как много энергии АКБ может отдать сразу. Широкий шланг - дрон резко разгоняется. Узкий - на полном газу АКБ \"задыхается\".","pic":"hose"},{"h":"S - сила напора","p":"Больше банок (S) - выше напряжение, моторы крутятся быстрее. Но ставить можно только АКБ с тем числом банок, на которое рассчитан дрон: 6S в дрон для 4S сожжёт моторы и регулятор.","pic":"stack"},{"h":"Просадка на газу","p":"На полном газу вольты на время падают (просадка), а когда отпускаешь газ, немного поднимаются. Поэтому садимся по тем вольтам, что видим на спокойном полёте.","pic":"sag"}]},{"s":"game","h":"Тренажёр: сравни две АКБ","g":"compare","n":5},{"s":"quiz","h":"Проверь себя","n":5,"pool":[["Что показывает число mAh?",["Ёмкость: сколько энергии в баке","Напряжение","Скорость зарядки"],"mAh - ёмкость, \"размер бака\" с энергией."],["Что показывает число C?",["Сколько энергии АКБ может отдать сразу","Сколько банок","Температуру"],"C - токоотдача, \"ширина шланга\": сколько энергии АКБ может отдать сразу."],["Какая АКБ даст дольше полёт на том же дроне?",["1500 mAh","850 mAh","Одинаково"],"Больше mAh - больше бак, дольше летаем."],["Почему нельзя просто поставить огромную АКБ?",["Она тяжёлая - дрон станет медленным и неповоротливым","Она не влезет в очки","Можно, всегда лучше"],"Тяжёлая АКБ делает дрон медленным и неповоротливым, и моторы тратят больше энергии."],["Что происходит с вольтами на полном газу?",["Временно проседают","Растут","Не меняются"],"На газу АКБ отдаёт большой ток, и вольты временно падают - это просадка."],["Какая АКБ мощнее при той же ёмкости?",["6S","4S","Одинаково"],"Больше банок - выше напряжение - моторы крутятся быстрее. Но ставят только ту АКБ, на которую рассчитан дрон."],["Какой максимальный ток у АКБ 1300 mAh 100C?",["130 А","13 А","1300 А"],"100 x 1,3 А = 130 А."],["Почему садиться нужно по вольтам на спокойном полёте, а не на газу?",["На газу вольты временно занижены просадкой","На газу датчик выключается","Разницы нет"],"На газу вольты временно ниже из-за просадки, по ним легко ошибиться."],["Зимой АКБ быстрее \"садится\". Почему?",["На холоде банки хуже отдают ток и сильнее проседают","Зимой дрон тяжелее","Холод заряжает АКБ"],"На холоде банки хуже отдают ток и сильнее проседают."]],"x":[["Бак машины и mAh: что общего?",["Оба показывают, сколько энергии в запасе","Оба про скорость","Ничего"],"Оба показывают запас энергии."],["Широкий шланг - это...",["Высокое число C","Высокое число mAh","Много банок"],"Широкий шланг = много энергии сразу = высокое C."],["На газу в очках 13,2 В, отпустил газ - 14,6 В. Почему?",["Это просадка на газу, она проходит","Сломался датчик","АКБ зарядилась в полёте"],"Это просадка: на газу вольты падают, без газа возвращаются."],["Тренер дал АКБ 650 mAh вместо 450 mAh. Что изменится?",["Полёт дольше, дрон тяжелее","Дрон мощнее в 2 раза","Ничего"],"Бак больше - полёт дольше, но АКБ тяжелее."],["Какой ток может отдать АКБ 450 mAh 80C?",["36 А","450 А","8 А"],"80 x 0,45 А = 36 А."]]}]},"fly_sim2":{"t":"Полёт: плавный газ","sub":"Летим ровно - АКБ меньше проседает","e":"🎮","pts":15,"fly":true,"steps":[{"s":"cards","h":"Задание","cards":[{"h":"Летим в симуляторе","p":"Выбери трассу в Квадросиме или Вороне. Пролети 3 круга без резких рывков газа: плавно прибавляй и плавно сбрасывай. Запиши лучшее время круга.","pic":"sim"},{"h":"Зачем плавный газ","p":"Каждый резкий рывок газа - это большой ток из АКБ. Вольты на мгновение проседают. Плавный газ - АКБ меньше устаёт, и летаешь дольше.","pic":"sag"}]},{"s":"fly","h":"Впиши результат","sims":["Квадросим","Ворон"]}]},"akb_label":{"t":"Читаем наклейку","sub":"\"4S 1500mAh 120C\" по частям","e":"🏷","pts":20,"steps":[{"s":"game","h":"Нажми на каждую часть наклейки","g":"label"},{"s":"cards","h":"Ещё два секрета","cards":[{"h":"Балансировочный разъём","p":"У АКБ из двух и больше банок два разъёма: силовой (толстые провода к дрону) и балансировочный (тонкие провода). Через балансир зарядка следит за каждой банкой. Проводов у балансира на один больше, чем банок: у 4S их 5. У однобаночной АКБ Mobula 7 разъём один - банка одна, балансир не нужен.","pic":"plug"},{"h":"Ток зарядки - \"1C\"","p":"Безопасный ток зарядки - 1C: ёмкость в амперах. 1500 mAh = 1,5 А, значит заряжаем током 1,5 А. 450 mAh - током 0,45 А.","pic":"charge"}]},{"s":"quiz","h":"Проверь себя","n":6,"xall":1}]},"akb_care":{"t":"Зарядка и хранение","sub":"Как не устроить пожар и продлить жизнь АКБ","e":"🧯","pts":25,"steps":[{"s":"cards","h":"Правила","cards":[{"h":"Заряжаем только под присмотром","p":"АКБ заряжаем подходящей зарядкой (для 2S и больше - с балансиром), только когда рядом взрослый. Не уходим из комнаты и не заряжаем на ночь.","pic":"charge"},{"h":"Огнеупорный мешок","p":"Заряжаем и храним АКБ в огнеупорном мешке или металлическом ящике, подальше от всего, что горит.","pic":"bag"},{"h":"Не в тепле и не на холоде","p":"Нельзя класть АКБ на батарею, на солнце или в горячую машину. Зимой не заряжаем холодную АКБ: сначала пусть согреется до комнатной температуры.","pic":"temp"},{"h":"Вздулась - не летаем","p":"Если АКБ стала пухлой, мягкой или помятой, на ней нельзя летать и нельзя её заряжать. Отдаём тренеру. Выбрасывать в обычный мусор нельзя.","pic":"swell"},{"h":"Горячая после полёта","p":"После полёта АКБ тёплая. Сразу на зарядку не ставим - даём ей остыть.","pic":"hot"}]},{"s":"game","h":"Найди ошибки в истории","g":"story","story":[["Петя отлетал и сразу поставил горячую АКБ на зарядку.",1,"Сначала АКБ должна остыть."],["Он положил АКБ в огнеупорный мешок.",0,"Верно, так безопаснее."],["Зарядку включил в режиме LiPo для обычной LiPo-АКБ.",0,"Верно, режим должен совпадать с АКБ."],["Пока заряжалось, Петя ушёл гулять на два часа.",1,"Заряжаем только под присмотром."],["Одна АКБ оказалась пухлой, и Петя решил на ней ещё полетать.",1,"Вздутую АКБ не используем, отдаём тренеру."],["Перед отъездом на неделю Петя перевёл АКБ в режим хранения.",0,"Верно, около 3,8 В на банку."],["Запасную АКБ он положил на батарею, чтобы не замёрзла.",1,"АКБ нельзя греть на батарее."],["Он подключил балансировочный разъём к зарядке.",0,"Верно, так зарядка следит за каждой банкой."],["Обычную LiPo Петя зарядил в режиме LiHV до 4,35 В на банку.",1,"Обычную LiPo заряжаем только до 4,2 В."]]},{"s":"quiz","h":"Проверь себя","n":5,"pool":[["Где заряжать АКБ?",["В огнеупорном мешке, под присмотром взрослого","На диване ночью","На батарее, чтобы быстрее"],"Огнеупорный мешок и присмотр взрослого - главные правила зарядки."],["АКБ вздулась. Что делаем?",["Не летаем, не заряжаем, отдаём тренеру","Прижимаем и летаем","Заряжаем на маленьком токе"],"Вздутие - газ внутри повреждённой банки. Такая АКБ может загореться."],["АКБ горячая после полёта. Как правильно?",["Дать остыть, потом заряжать","Сразу на зарядку","Положить в морозилку"],"Горячую банку заряжать вредно и опасно. Сначала пусть остынет."],["Зимой принесли АКБ с мороза. Что делать?",["Дать согреться до комнатной температуры","Сразу заряжать","Греть феном на батарее"],"Холодную АКБ заряжать нельзя - она портится. Ждём комнатной температуры."],["Куда девать старую испорченную АКБ?",["Отдать тренеру на утилизацию","В обычный мусор","Закопать"],"Литиевые АКБ сдают на утилизацию, в обычном мусоре они могут загореться."],["Можно ли оставить АКБ на зарядке и уйти гулять?",["Нет, только под присмотром","Да, зарядка умная","Да, если ненадолго"],"Если что-то пойдёт не так, рядом должен быть человек."],["Зачем зарядке балансир?",["Чтобы ни одна банка не перезарядилась","Чтобы было красиво","Для скорости"],"Банки заряжаются немного по-разному. Балансир выравнивает каждую, чтобы ни одна не перезарядилась."],["АКБ задымилась на зарядке. Первый шаг?",["Отключить зарядку от розетки и позвать взрослого","Схватить АКБ руками","Открыть мешок и посмотреть, что внутри"],"Сначала обесточить: отключить зарядку от розетки, отойти и позвать взрослого."]],"x":[["Маша положила АКБ на солнце на подоконник. Это...",["Ошибка: АКБ нельзя греть","Правильно","Так АКБ заряжается"],"Нагрев портит АКБ и может привести к пожару."],["Что опаснее всего для АКБ?",["Прокол, удар и перегрев","Наклейка","Бутылка воды рядом"],"Прокол, удар и перегрев могут вызвать замыкание и пожар."],["Ты увидел, что АКБ стала пухлой. Твой первый шаг?",["Сказать тренеру и отложить её","Поставить на зарядку проверить","Полетать аккуратно"],"Пухлую АКБ откладываем и говорим тренеру."],["Почему зарядку не ставят на ночь?",["Ночью никто не увидит, если что-то пойдёт не так","Ночью электричество хуже","Так дольше"],"Ночью все спят, и никто не заметит, если что-то пойдёт не так."],["Где лучше хранить АКБ дома?",["В огнеупорном мешке или металлическом ящике","В рюкзаке с книгами","Под подушкой"],"Огнеупорный мешок или металлический ящик удержит огонь, если что-то случится."]]}]},"fly_mob":{"t":"Полёт на Mobula 7 с тренером","sub":"Следим за вольтами в очках вживую","e":"🚁","pts":25,"steps":[{"s":"cards","h":"Задание на занятии","cards":[{"h":"Летим вживую","p":"На занятии с тренером взлетаешь на Mobula 7. В очках следи за напряжением. Когда увидишь около 3,5 В на банку на спокойном полёте - садись.","pic":"mob"},{"h":"После посадки","p":"Дизарм, отключи АКБ, запомни, сколько вольт было при посадке. Впиши число ниже и нажми \"Сделал\". Тренер подтвердит.","pic":"scale"}]},{"s":"fly","h":"Впиши результат","live":true},{"s":"coach","h":"Тренер принимает","p":"Тренер видел полёт и посадку вовремя."}]},"akb_rep":{"t":"Повторение: безопасность и устройство","sub":"Знакомые темы - вопросы с другой стороны","e":"🔁","pts":20,"steps":[{"s":"quiz","h":"Вспомни модули 1 и 2","n":6,"pool":[["Дрон упал в траву, моторы ещё гудят и дёргаются. Что первым делом?",["Дизарм","Бегу поднимать","Даю газ, чтобы взлетел"],"Дизарм блокирует моторы - это первое действие при любой аварии."],["Друг хочет поймать заармленный дрон рукой. Ты скажешь...",["Стоп! Сначала дизарм, к заармленному не подходим","Лови, он маленький","Только в перчатке"],"Заармленный дрон может резко раскрутить винты. Сначала дизарм."],["Где во время полёта должны стоять зрители?",["За сеткой или линией безопасности","Под трассой","Рядом с воротами"],"Зрители всегда за сеткой или линией безопасности."],["Зачем пилоту в очках наблюдатель?",["Он видит дрон и людей вокруг","Чтобы держать пульт","Для фото"],"Пилот видит только картинку с камеры. Наблюдатель видит дрон и людей вокруг."],["Почему соседние винты крутятся в разные стороны?",["Чтобы дрон не закручивало вокруг себя","Для красоты","Чтобы экономить АКБ"],"Иначе их вращение закручивало бы весь дрон вокруг своей оси."],["Какая деталь получает команды с пульта?",["Приёмник","Видеопередатчик","Камера"],"Приёмник ловит сигнал пульта и передаёт его полётному контроллеру."],["Что делает регулятор (ESC)?",["Управляет скоростью моторов","Показывает видео","Заряжает АКБ"],"Регулятор получает команду от контроллера и управляет оборотами моторов."],["Куда идёт картинка с камеры дрона?",["Через видеопередатчик в очки пилота","В пульт","В полётный контроллер и там остаётся"],"Камера - видеопередатчик - антенна - очки пилота."],["Что такое failsafe?",["Что сделает дрон, если пропадёт связь с пультом","Режим быстрого полёта","Название рамы"],"Failsafe - заранее заданное действие, если пропал сигнал пульта (например, выключить моторы)."]],"x":[["Пропало видео в очках. Первое действие?",["Дизарм","Продолжаю лететь по памяти","Даю полный газ вверх"],"Без видео пилот слеп - сначала дизарм."],["Кто даёт команду на запуск на занятии?",["Тренер или судья","Любой пилот","Зрители"],"На занятии запуск разрешает тренер или судья."],["Без какой детали дрон не получит команду \"вперёд\"?",["Приёмник","Камера","Наклейка на АКБ"],"Команды пульта принимает приёмник."],["Видеопередатчик сломался. Что пропадёт?",["Картинка в очках","Связь с пультом","Питание моторов"],"Видеопередатчик отправляет картинку в очки. Управление останется."],["Зачем перед полётом проверять винты?",["Треснувший винт может отломиться в полёте","Чтобы были чистыми","Не нужно"],"Треснувший винт может разлететься в полёте."]]}]},"akb_final":{"t":"Итог модуля","sub":"Финальная проверка и АКБ к полёту на занятии","e":"🎓","pts":30,"final":true,"steps":[{"s":"quiz","h":"Финальный тест: 10 вопросов","n":10,"pass":0.8,"from":["akb_inside","akb_volt","akb_cap","akb_care"],"xall":1},{"s":"coach","h":"Подготовь АКБ к полёту","p":"На занятии: проверь АКБ на вздутие и повреждения, измерь напряжение, скажи, можно ли на ней лететь и почему. Тренер принимает."}]},"m4_sticks":{"t":"Стики и что делает каждый","sub":"Газ, поворот, наклоны - и как ими работать","e":"🕹","pts":20,"steps":[{"s":"cards","h":"Два стика - четыре движения","cards":[{"h":"Два стика, четыре оси","p":"У пульта два стика. Каждый ходит вверх-вниз и влево-вправо - всего 4 движения. Мы летаем в раскладке Mode 2. Левый стик - \"как высоко и куда смотрит нос\". Правый стик - \"куда лететь\".","pic":"e:🕹"},{"h":"Газ - как лифт","p":"Левый стик вверх - моторы крутятся быстрее, дрон поднимается. Вниз - опускается. Газ не прыгает в центр сам: где оставил стик, там он и стоит. Висит дрон где-то посередине, у каждого дрона своя точка.","pic":"e:⬆️"},{"h":"Рыскание - поворот на месте","p":"Левый стик влево-вправо - дрон поворачивается вокруг себя, как стрелка компаса. Он не летит в сторону, а меняет, куда смотрят нос и камера.","pic":"e:🔄"},{"h":"Тангаж и крен - наклоны","p":"Правый стик вперёд - дрон наклоняет нос и летит вперёд. Назад - летит назад. Вбок - наклоняется на бок и летит вбок. Запомни: дрон летит туда, куда наклонён.","pic":"quad"},{"h":"Маленькие движения","p":"Стики очень чуткие. Двигай их плавно и на чуть-чуть, как будто рисуешь тонким карандашом. Резкий рывок стика - резкий бросок дрона.","pic":"e:🤏"},{"h":"Управляешь \"из кабины\"","p":"В FPV ты видишь полёт глазами дрона, поэтому \"вправо\" всегда вправо. А если смотреть на дрон со стороны, когда он летит носом к тебе, всё кажется наоборот: стик вправо - а дрон уходит влево от тебя. Поэтому со стороны новичкам сложнее.","pic":"ochki"}]},{"s":"game","h":"Тренажёр: какой стик?","g":"sort","tip":"левый - газ и поворот носа на месте, правый - все наклоны: вперёд, назад, вбок.","cats":["Левый стик","Правый стик"],"items":[["Подняться выше",0,"Газ - левый стик вверх."],["Полететь вперёд",1,"Тангаж - правый стик вперёд."],["Повернуть нос налево на месте",0,"Рыскание - левый стик влево."],["Сдвинуться вбок, не поворачивая нос",1,"Крен - правый стик вбок."],["Мягко опуститься на пол",0,"Газ - левый стик плавно вниз."],["Полететь назад",1,"Тангаж - правый стик назад."],["Затормозить дрон, который летит вперёд",1,"Правый стик чуть назад - дрон наклоняется назад и тормозит."],["Развернуть камеру на ворота, не сдвигаясь",0,"Поворот на месте - рыскание, левый стик."],["Добавить тяги на наклоне, чтобы не терять высоту",0,"Тяга - это газ, левый стик."]]},{"s":"quiz","h":"Проверь себя","n":5,"pool":[["В раскладке Mode 2 газ - это...",["Левый стик вверх-вниз","Правый стик вперёд-назад","Левый стик влево-вправо"],"В Mode 2 газ - левый стик вверх-вниз."],["Ты отпустил стик газа. Что он сделает?",["Останется на месте","Сам вернётся в центр","Сам упадёт вниз до нуля"],"Газ не пружинит: стик остаётся там, где его оставили."],["Как дрон летит вперёд?",["Наклоняет нос вперёд и летит туда","Поднимает нос и летит вверх","Выключает задние моторы"],"Правый стик вперёд: дрон наклоняет нос и летит туда, куда наклонён."],["Левый стик вправо. Что сделает дрон?",["Повернётся направо на месте","Полетит вправо боком","Поднимется выше"],"Это рыскание: дрон поворачивается на месте вокруг себя."],["Как новичку правильно двигать стики?",["Плавно и понемногу","Быстрыми рывками","Сразу до упора"],"Стики чуткие: маленькое движение стика - заметное движение дрона."],["Дрон медленно опускается при висении. Что поправить?",["Чуть добавить газ","Правый стик вперёд","Левый стик влево"],"Чуть больше газа - и дрон перестанет снижаться."],["Что такое крен (roll)?",["Наклон на бок, дрон летит вбок","Поворот на месте","Наклон носом вперёд"],"Крен - наклон на левый или правый бок, дрон летит вбок."],["Почему на наклоне вперёд дрон теряет высоту?",["Часть тяги уходит вперёд, вверх меньше","Задние моторы выключаются","Так срабатывает failsafe"],"Часть тяги уходит вперёд, вверх тянет меньше. Поэтому чуть добавляют газ."],["К концу полёта, чтобы висеть, газа нужно...",["Чуть больше","Чуть меньше","Ровно столько же"],"АКБ садится, вольт меньше - для той же тяги нужно чуть больше газа."],["Как держат стики \"щипком\"?",["Большим и указательным пальцем","Всей ладонью сверху","Одним указательным пальцем"],"Щипок - стик между большим и указательным пальцем, так точнее мелкие движения."]],"x":[["Какой стик в Mode 2 отвечает за наклоны вперёд и вбок?",["Правый","Левый","Оба по очереди"],"Правый стик - тангаж и крен."],["Хочешь посмотреть камерой на ворота, не сдвигаясь. Что делаешь?",["Левый стик вбок","Правый стик вбок","Газ вверх"],"Поворот на месте - левый стик вбок (рыскание)."],["Дрон уплывает назад при висении. Поправка?",["Чуть правый стик вперёд","Чуть газ вниз","Левый стик вправо"],"Чуть правый стик вперёд - дрон вернётся на место."],["Что такое тангаж (pitch)?",["Наклон носом вперёд или назад","Поворот на месте","Подъём вверх"],"Тангаж - наклон носом вперёд или назад."]]}]},"m4_modes":{"t":"Режимы Angle и Acro","sub":"Простыми словами: кто выравнивает дрон","e":"🎚","pts":20,"steps":[{"s":"cards","h":"Характер дрона","cards":[{"h":"Режим - это характер дрона","p":"Режим полёта решает, что делает дрон, когда ты двигаешь и отпускаешь правый стик. Режим переключают тумблером на пульте. Главные режимы: Angle и Acro.","pic":"e:🎚"},{"h":"Angle - \"сам выравнивается\"","p":"В Angle стик задаёт наклон: чуть вперёд - чуть наклонился, сильно - сильно. Отпустил стик - дрон сам встал ровно. Перевернуться он не может. Это режим для первых полётов, как велосипед с боковыми колёсиками.","pic":"e:🧘"},{"h":"Acro - \"держит, как оставил\"","p":"В Acro стик задаёт, как быстро дрон поворачивается. Отпустил стик - дрон замер в том наклоне, который был, и летит дальше. Выровнять его - твоя работа. Зато можно сделать флип и полететь как угодно. На Acro летают гонщики.","pic":"e:🤸"},{"h":"Horizon - посередине","p":"Horizon похож на Angle, пока стик около центра: дрон выравнивается. А если увести стик до упора, дрон может перевернуться, как в Acro. Многие пилоты переходят с Angle сразу на Acro.","pic":"e:🌅"},{"h":"Высоту держишь ты","p":"В Angle и в Acro дрон сам высоту не держит. Angle выравнивает только наклон. Газ - всегда работа пилота.","pic":"e:↕️"},{"h":"Путь пилота","p":"Начинаем в Angle: в симуляторе и на Mobula 7 в зале. Когда висение, круг и ворота получаются уверенно, тренер переводит на Acro - сначала в симуляторе.","pic":"sim"}]},{"s":"game","h":"Тренажёр: Angle или Acro?","g":"sort","tip":"Angle сам выравнивает и не даёт перевернуться, в Acro дрон держит наклон и выравнивает пилот.","cats":["Angle","Acro"],"items":[["Отпустил правый стик - дрон сам выравнивается",0,"Это самовыравнивание Angle."],["Отпустил правый стик - дрон остаётся в наклоне",1,"В Acro наклон сохраняется."],["Перевернуться (флип) нельзя",0,"В Angle угол наклона ограничен."],["Можно сделать флип",1,"В Acro наклон не ограничен."],["Удобен для первых полётов",0,"Дрон сам встаёт ровно - новичку проще."],["Пилот сам выравнивает дрон",1,"В Acro выравнивать - работа пилота."],["Стик задаёт угол наклона",0,"В Angle: дальше стик - сильнее наклон."],["Стик задаёт скорость вращения",1,"В Acro: дальше стик - быстрее вращение."],["На нём летают гонщики",1,"Acro даёт полную свободу и точный ответ на стик."],["Нужен акселерометр",0,"Angle узнаёт, где низ, по акселерометру."]]},{"s":"quiz","h":"Проверь себя","n":5,"pool":[["Ты отпустил правый стик в режиме Angle. Что сделает дрон?",["Сам выровняется","Останется в наклоне","Перевернётся"],"В Angle дрон сам возвращается в горизонт."],["Ты отпустил правый стик в режиме Acro. Что сделает дрон?",["Останется в том наклоне, что был","Сам выровняется","Выключит моторы"],"В Acro дрон сохраняет наклон, который был. Выравнивает пилот."],["Какой режим для первых полётов?",["Angle","Acro","Любой, разницы нет"],"Angle сам выравнивает дрон и не даёт перевернуться."],["В каком режиме можно сделать флип?",["Acro","Angle","Ни в каком"],"В Acro наклон не ограничен - можно перевернуться."],["Чем переключают режим полёта?",["Тумблером на пульте","Кнопкой на дроне","Сменой АКБ"],"Режим ставят на тумблер пульта."],["Держит ли режим Angle высоту сам?",["Нет, газом управляет пилот","Да, всегда","Да, если отпустить газ"],"Angle выравнивает только наклон, газом управляет пилот."],["Что задаёт стик в режиме Acro?",["Скорость вращения дрона","Угол наклона","Высоту полёта"],"В Acro стик задаёт скорость вращения по оси."],["Какой датчик нужен режиму Angle, чтобы знать, где \"ровно\"?",["Акселерометр","Камера","Приёмник"],"Акселерометр чувствует, где низ, - по нему дрон выравнивается."],["Чем Horizon отличается от Angle?",["На полном стике может перевернуться","Он сам держит высоту","Он совсем не выравнивается"],"Около центра Horizon выравнивается, а на полном стике может перевернуться."],["Почему гонщики летают в Acro?",["Полная свобода и точный ответ на стик","Он сам облетает ворота","Он меньше тратит АКБ"],"Дрон точно делает то, что велел пилот, и наклон не ограничен."]],"x":[["Режим, где дрон сам встаёт ровно, называется...",["Angle","Acro","Rate"],"Angle - режим самовыравнивания."],["В режиме Acro дрон выравнивает...",["Пилот","Сам дрон","Тренер с земли"],"В Acro выравнивает пилот."],["Кто в клубе решает, в каком режиме ты летаешь?",["Тренер","Сосед по трассе","Симулятор сам"],"Режим выбирает тренер - по твоим успехам."],["Стик в центре в режиме Acro значит...",["Вращения нет, наклон сохранился","Дрон выровнялся","Моторы выключены"],"Вращение остановилось, наклон сохранился."]]}]},"m4_trainer":{"t":"Тренажёр стиков","sub":"Как тренировать руки: настройка, упражнения, поправки","e":"🎯","pts":20,"steps":[{"s":"cards","h":"Тренируем руки","cards":[{"h":"Сначала настрой пульт","p":"Подключи пульт к компьютеру и в симуляторе сделай калибровку стиков: подвигай каждый стик до упора во все стороны. Проверь: газ внизу - 0, вверху - 100%. Иначе дрон будет вести себя странно.","pic":"sim"},{"h":"Упражнение \"точка\"","p":"Взлети и держи дрон над одной точкой. Уплыл - поправь чуть-чуть в обратную сторону и сразу верни стик. Поправки маленькие и частые, а не большие и редкие.","pic":"e:📍"},{"h":"Упражнение \"поворот на месте\"","p":"Вися на месте, медленно повернись на полный круг левым стиком. Высота не должна меняться, дрон не должен уплывать. Потом то же в другую сторону.","pic":"e:🔄"},{"h":"От простого к сложному","p":"Тренируемся по шагам, как по лесенке. К следующему шагу - когда текущий получается 3 раза подряд.","pic":"chain:Висение>Вперёд-назад>Вбок>Поворот>Круг>Восьмёрка>Ворота"},{"h":"Смотри вперёд","p":"Смотри туда, куда хочешь прилететь, а не прямо перед носом дрона. Тогда успеешь поправить заранее.","pic":"e:👀"}]},{"s":"game","h":"Тренажёр: стики по порядку","g":"order","sets":[{"q":"Взлёт и висение","items":["Сказать \"Взлетаю!\"","Арм","Плавно добавлять газ до отрыва","Чуть убрать газ и зависнуть"],"why":"Сначала предупреждение и арм, потом плавный газ."},{"q":"Пролететь вперёд и остановиться (режим Angle)","items":["Правый стик чуть вперёд","Чуть добавить газ, чтобы не терять высоту","Правый стик чуть назад - затормозить","Убрать лишний газ и зависнуть"],"why":"Наклон - газ - торможение заранее - висение."},{"q":"Посадка","items":["Сказать \"Сажусь!\"","Зависнуть над местом посадки","Плавно убирать газ до касания","Газ в ноль и дизарм"],"why":"Мягкая посадка - из висения, плавным газом."},{"q":"Поворот на месте на полный круг","items":["Зависнуть ровно","Плавно увести левый стик вбок","Держать газом высоту, пока дрон поворачивается","Вернуть стик в центр, когда нос смотрит туда, откуда начал"],"why":"Поворот - левым стиком, высоту держим газом."}]},{"s":"quiz","h":"Проверь себя","n":5,"pool":[["Зачем калибровать стики в симуляторе?",["Чтобы симулятор правильно понимал стики","Чтобы зарядить пульт","Чтобы включить видео"],"Без калибровки симулятор неправильно понимает, где у стика центр и края."],["Дрон уплывает влево при висении. Поправка?",["Чуть правый стик вправо","Левый стик влево","Газ до упора вверх"],"Чуть правый стик вправо - и сразу обратно в центр."],["Какие поправки лучше при висении?",["Маленькие и частые","Большие и редкие","Никаких, пусть летит"],"Маленькие и частые поправки держат дрон точнее."],["Когда переходить к следующему упражнению?",["Когда текущее получилось 3 раза подряд","Сразу после первой попытки","Когда текущее надоело"],"Шаг пройден, когда получается уверенно 3 раза подряд."],["Куда смотреть в полёте?",["Туда, куда хочу прилететь","Только на цифры в углу","Прямо под дрон"],"Смотрим туда, куда хотим прилететь, - тогда поправки вовремя."],["Как приземлиться мягко?",["Зависнуть и плавно убрать газ","Сбросить газ в ноль с высоты","Коснуться пола на ходу"],"Зависаем над точкой и плавно убираем газ."],["Ты повернулся на месте, а дрон заодно опустился. Что тренировать?",["Держать высоту газом во время поворота","Поворачиваться быстрее","Поворачиваться правым стиком"],"Во время поворота газ держат ровно - это упражнение \"поворот на месте\"."],["Почему короткие тренировки каждый день лучше одной длинной в неделю?",["Руки лучше запоминают частые повторения","Так меньше устаёт компьютер","Разницы никакой нет"],"Руки запоминают движения от частых повторений."],["В симуляторе газ вверх, а дрон опускается. Что не так?",["Ось газа перевёрнута в настройках","Села АКБ пульта","Сломался гироскоп"],"Ось газа перевёрнута - её меняют в настройках симулятора."],["Ты начал тормозить, а дрон ещё летит вперёд. Почему?",["Он летит по инерции, тормозить надо раньше","Сломался правый стик","Выключился режим Angle"],"Дрон разогнался и по инерции летит дальше. Тормозить надо заранее."]],"x":[["Дрон уплывает вперёд при висении. Поправка?",["Чуть правый стик назад","Чуть газ вверх","Левый стик вправо"],"Чуть правый стик назад."],["Что делаем перед первым полётом в симуляторе?",["Калибруем стики","Ставим самую высокую скорость","Ничего не нужно"],"Калибруем стики."],["Что идёт сразу после висения в лесенке упражнений?",["Полёт вперёд и назад","Восьмёрка","Ворота на скорости"],"Висение - вперёд-назад - вбок - поворот - круг - восьмёрка - ворота."],["Дрон раскачивается вокруг точки. Причина?",["Слишком большие поправки","Слишком маленький газ висения","Плохая погода в симуляторе"],"Слишком большие поправки."]]}]},"m4_moves":{"t":"Фигуры: висение, круг, восьмёрка, ворота","sub":"Как выполнить каждую и на что смотреть","e":"♾️","pts":20,"steps":[{"s":"cards","h":"Четыре фигуры","cards":[{"h":"Висение","p":"Висение - основа всего. Дрон держится в одной точке на одной высоте. Получается висение - получится и всё остальное.","pic":"e:📍"},{"h":"Круг","p":"Летим вокруг предмета: правый стик ведёт вперёд и чуть вбок, левый понемногу поворачивает нос. Газ держим ровно.","pic":"e:⭕"},{"h":"Восьмёрка","p":"Восьмёрка - два круга вокруг двух предметов, в разные стороны. В середине меняешь направление поворота: был левый - стал правый.","pic":"e:♾️"},{"h":"Ворота","p":"Ворота - рамка, через которую пролетаем. Заранее выровняй высоту и нос на центр ворот. В воротах летим прямо, не поворачиваем.","pic":"e:🚪"},{"h":"Вживую в зале","p":"Всё это делаем в зале на Mobula 7 с тренером, после симулятора. Перед взлётом: людей на площадке нет, наблюдатель рядом, тренер разрешил, говорим \"Взлетаю!\"","pic":"mob"}]},{"s":"game","h":"Тренажёр: фигура и как её делать","g":"match","pairs":[["Висение","дрон держится в одной точке"],["Круг","полёт вокруг одного предмета"],["Восьмёрка","два круга в разные стороны"],["Ворота","рамка, через которую пролетаем"],["Мягкая посадка","зависнуть и плавно убрать газ"],["Разворот на месте","только левый стик вбок"],["Середина восьмёрки","смена стороны поворота"]]},{"s":"quiz","h":"Проверь себя","n":5,"pool":[["Какая фигура - основа всех остальных?",["Висение","Восьмёрка","Флип"],"Без уверенного висения не получатся ни круг, ни ворота."],["Что такое восьмёрка?",["Два круга в разные стороны","Восемь кругов подряд","Восемь ворот подряд"],"Это два круга вокруг двух предметов в разные стороны."],["Как пролетать ворота?",["Выровняться заранее и лететь прямо через центр","Повернуть прямо в воротах","Пролететь над воротами"],"Выравниваемся заранее и летим через центр прямо."],["Что держим ровно при облёте круга?",["Газ - чтобы не менялась высота","Только правый стик","Ничего, всё само"],"Газ держим ровно, чтобы высота не менялась."],["Где тренируем фигуры вживую?",["В зале на Mobula 7 с тренером","Во дворе одни","На улице у дороги"],"В зале на Mobula 7 с тренером."],["Что самое сложное в восьмёрке?",["Смена стороны поворота в середине","Взлёт","Первые три секунды"],"В середине нужно плавно переложить крен и поворот в другую сторону."],["Чем больше крен при облёте точки, тем круг...",["Меньше","Больше","Не меняется"],"Больше наклон - сильнее поворачиваем - круг меньше."],["Куда смотреть, пролетая ворота?",["Сквозь ворота, туда, куда полечу дальше","На раму ворот","Вниз на пол"],"Сквозь ворота, дальше - туда, куда полетишь потом."],["Какое висение считается хорошим?",["Дрон на месте, высота не прыгает","Дрон медленно плывёт по кругу","Дрон то поднимается, то опускается"],"Дрон долго держится на одном месте, высота не прыгает."]],"x":[["Висение - это...",["Дрон держится в одной точке","Полёт по кругу","Пролёт ворот"],"Дрон держится в одной точке."],["В самих воротах лучше...",["Лететь прямо","Резко повернуть","Сбросить газ"],"Лететь прямо, не поворачивать."],["Сколько предметов облетаем в восьмёрке?",["Два","Один","Восемь"],"Два: по кругу вокруг каждого."],["Разворот на месте делают...",["Левым стиком вбок","Правым стиком вперёд","Только газом"],"Только левым стиком вбок."]]}]},"m4_fly8":{"t":"Полёт: восьмёрка и ворота","sub":"Квадросим или Ворон: смена поворота и точный пролёт","e":"🎮","pts":15,"fly":true,"steps":[{"s":"cards","h":"Задание","cards":[{"h":"Летим в симуляторе","p":"В симуляторе выбери два предмета рядом (два дерева, два столба или двое ворот). Облети их восьмёркой 2 раза, не задев и не касаясь земли. Запиши время.","pic":"sim"},{"h":"О чём думать","p":"В середине восьмёрки плавно перекладывай крен и поворот на другую сторону и держи газ ровно. К воротам выравнивайся издалека и смотри сквозь них. Летай в Angle, пока тренер не скажет перейти на Acro.","pic":"e:♾️"}]},{"s":"fly","h":"Впиши результат","sims":["Квадросим","Ворон"]}]},"m4_rep":{"t":"Повторение: устройство и АКБ","sub":"История Коли и вопросы глазами пилота","e":"🔁","pts":20,"steps":[{"s":"game","h":"Найди ошибки Коли","g":"story","tip":"вспомни винты, видеоканал, плавный газ, вольты для посадки и число банок АКБ.","story":[["Коля посмотрел наклейку АКБ: 1S, как и нужно для Mobula 7.",0,"Верно, дрону нужна АКБ с его числом банок."],["Он заметил, что один винт стоит не той стороной, но решил, что и так взлетит.",1,"Перевёрнутый винт гонит воздух не туда: дрон перевернётся при взлёте."],["Коля поставил в очках свой канал и проверил, что картинка чёткая.",0,"Верно, свой канал - чистая картинка."],["Сразу после взлёта он стал дёргать газ рывками, чтобы \"разогреть\" АКБ.",1,"Рывки газа - большой ток и просадка. Газ должен быть плавным."],["В режиме Angle Коля отпустил правый стик, и дрон выровнялся сам.",0,"Верно, в Angle контроллер сам выравнивает дрон по датчикам."],["Когда в очках показало 3,5 В на банку, Коля решил сделать ещё пять кругов.",1,"3,5 В на банку - пора садиться."],["Картинка зарябила, и Коля сразу посадил дрон и проверил антенну.",0,"Верно, сначала безопасность, потом поиск причины."],["Чтобы летать дольше, Коля взял АКБ 2S: \"две банки - значит, бак вдвое больше\".",1,"Банки \"этажами\" (S) дают больше вольт, а не больше бака. Ставим только АКБ, на которую рассчитан дрон."],["После посадки Коля сделал дизарм, отключил АКБ и дал ей остыть.",0,"Верно."],["Запасные АКБ Коля хранит в огнеупорном мешке, около 3,8 В на банку.",0,"Верно, так безопасно и АКБ живут дольше."]]},{"s":"quiz","h":"Вспомни модули 2 и 3 по-новому","n":5,"pool":[["Ты двигаешь правый стик вперёд. Какая деталь на дроне первой получит команду?",["Приёмник","Камера","Видеопередатчик"],"Пульт - приёмник - контроллер - регулятор - мотор."],["В полёте в очках 3,5 В на банку. Что делаешь?",["Сажусь","Лечу ещё круг на полном газу","Переключаю режим на Acro"],"3,5 В на банку в спокойном полёте - пора садиться."],["Резко дал газ - вольты в очках упали, отпустил - вернулись. Что это?",["Просадка на газу","АКБ сломалась","Сломался видеопередатчик"],"Это просадка на газу, она проходит."],["Картинка в очках зарябила, как только взлетел соседний пилот. Вероятная причина?",["Мы на одном видеоканале","Села АКБ пульта","Сломался мотор"],"Скорее всего, вы на одном видеоканале."],["После полёта АКБ тёплая. Сразу на зарядку?",["Нет, сначала пусть остынет","Да, так быстрее","Да, если АКБ маленькая"],"Сначала даём АКБ остыть."],["Почему дрон может поворачиваться на месте стиком рыскания?",["Пары винтов крутятся в разные стороны, их обороты меняют","У дрона есть маленький руль","Его поворачивает поток воздуха от камеры"],"Пары винтов крутятся в разные стороны. Если одну пару раскрутить сильнее, дрон поворачивается."],["К концу полёта дрон висит на большем газу, чем в начале. Почему?",["Вольт стало меньше, нужно больше газа","Винты стали тяжелее","Включился другой режим"],"АКБ разряжается, вольт меньше - для той же тяги нужно больше газа."],["Кто выравнивает дрон в режиме Angle?",["Полётный контроллер по датчикам","Регулятор сам","Видеопередатчик"],"Полётный контроллер по датчикам гироскопа и акселерометра."]],"x":[["Какая деталь крутит мотор так быстро, как велел контроллер?",["Регулятор","Приёмник","Антенна"],"Это регулятор (ESC)."],["Сколько банок в АКБ нашего Mobula 7?",["Одна (1S)","Четыре (4S)","Шесть (6S)"],"Mobula 7 летает на 1S - одна банка."],["АКБ - обычная LiPo, в очках 4,2 В на банку перед взлётом. Это...",["Полная АКБ","Пора садиться","Опасно мало"],"4,2 В - полная обычная LiPo."],["Почему в Mobula 7 нельзя ставить АКБ 2S?",["Дрон рассчитан на 1S, лишние вольты опасны","Она не влезет в очки","Можно, полёт будет дольше"],"Дрон рассчитан на 1S: лишние вольты могут сжечь электронику."]]}]},"m4_track":{"t":"Трасса с зачётным временем","sub":"Квадросим или Ворон: клубная трасса на время","e":"⏱","pts":20,"fly":true,"steps":[{"s":"cards","h":"Задание","cards":[{"h":"Летим в симуляторе","p":"Тренер называет клубную трассу в Квадросиме или Вороне и зачётное время. Пролети 3 круга без аварий и запиши лучшее время круга. Не уложился в зачёт - не страшно, попробуй ещё раз.","pic":"sim"},{"h":"Сначала чисто, потом быстро","p":"Круг без аварии почти всегда быстрее, чем быстрый круг с ударом о ворота. Плавный газ, выравнивание к воротам издалека и взгляд вперёд - вот главный секрет хорошего времени.","pic":"e:⏱"}]},{"s":"fly","h":"Впиши результат","sims":["Квадросим","Ворон"]},{"s":"coach","h":"Тренер принимает","p":"Тренер видел результат или запись экрана и подтверждает время."}]},"m4_coach":{"t":"На занятии: стики и Angle","sub":"Назови оси и покажи полёт на Mobula 7","e":"🧑‍🏫","pts":20,"steps":[{"s":"cards","h":"Что будет на занятии","cards":[{"h":"Покажи на пульте","p":"АКБ дрона отключена. Покажи на пульте и назови каждую ось: газ, рыскание, тангаж, крен. Покажи тумблер арма и тумблер режима. Расскажи, чем Angle отличается от Acro.","pic":"e:🕹"},{"h":"Полёт в Angle","p":"С разрешения тренера, на Mobula 7 в режиме Angle, наблюдатель рядом: \"Взлетаю!\", висение 30 секунд, полёт вперёд-назад и вбок, поворот на месте на полный круг, \"Сажусь!\", дизарм.","pic":"mob"}]},{"s":"coach","h":"Тренер принимает","p":"На занятии: назвал оси стиков и тумблеры, объяснил разницу Angle и Acro. На Mobula 7 в Angle повисел 30 секунд, слетал вперёд-назад и вбок, повернулся на месте на полный круг, сел и сделал дизарм. Тренер принимает."}]},"m4_final":{"t":"Тест \"Пилот\"","sub":"Финальная проверка и восьмёрка вживую","e":"🎓","pts":30,"final":true,"steps":[{"s":"quiz","h":"Тест \"Пилот\": 10 вопросов","n":10,"pass":0.8,"from":["m4_sticks","m4_modes","m4_trainer","m4_moves"],"xall":1},{"s":"coach","h":"Восьмёрка и ворота на Mobula 7","p":"На занятии: на Mobula 7 в режиме, который выбрал тренер, облетел восьмёрку вокруг двух отметок и пролетел ворота. Наблюдатель рядом, сказал \"Взлетаю!\" и \"Сажусь!\", всё включил и выключил по порядку. Тренер принимает."}]},"m5_race":{"t":"Что такое дрон-рейсинг","sub":"Трасса, заезды и путь к финалу","e":"🏁","pts":20,"steps":[{"s":"cards","h":"Гонки в воздухе","cards":[{"h":"Гонка дронов","p":"Дрон-рейсинг - это гонки FPV-дронов. Пилоты в очках летят по трассе из ворот и флагов. Кто быстрее и чище прошёл трассу, тот и выиграл. Это как картинг, только в воздухе.","pic":"e:🏁"},{"h":"Заезды","p":"Пилоты летят не все сразу, а заездами - по несколько человек, часто по 4. Пока один заезд в воздухе, следующие пилоты готовятся.","pic":"e:🥽🥽🥽🥽"},{"h":"Как проходит гонка","p":"Сначала тренировочные круги, чтобы изучить трассу. Потом квалификация: каждый показывает своё лучшее время. Лучшие пилоты летят дальше, а в финале решается, кто победил.","pic":"chain:Тренировка>Квалификация>Финал"},{"h":"Сначала симулятор","p":"Все гонщики много тренируются в симуляторе. Там трассу можно пролететь сто раз и не сломать ни одного винта. Мы делаем так же: Квадросим и Ворон, потом Mobula 7 в зале.","pic":"sim"}]},{"s":"game","h":"Тренажёр: найди пару","g":"match","pairs":[["Трасса","путь из ворот и флагов"],["Ворота","рамка, сквозь которую пролетают"],["Флаг","столбик, который облетают"],["Заезд","несколько пилотов летят вместе"],["Круг","один полный проход трассы"],["Квалификация","отбор по лучшему времени"],["Финал","решающий заезд лучших пилотов"],["Тренировочные круги","изучить трассу перед гонкой"]]},{"s":"quiz","h":"Проверь себя","n":5,"pool":[["Что такое дрон-рейсинг?",["Гонки FPV-дронов по трассе","Съёмка красивого видео с дрона","Полёты на самую большую высоту"],"Это гонки FPV-дронов по трассе из ворот и флагов."],["Как пилот видит трассу во время гонки?",["В очках, глазами дрона","Смотрит на дрон со стороны","По экрану телефона у судьи"],"Картинка с камеры дрона приходит в очки пилота."],["Что такое заезд?",["Группа пилотов, которые летят вместе","Один круг трассы","Разминка перед гонкой"],"Гонка идёт заездами: несколько пилотов летят вместе."],["Что пилот делает с воротами на трассе?",["Пролетает сквозь них","Облетает их сбоку","Садится рядом с ними"],"Сквозь ворота пролетают, а флаги облетают."],["Где гонщики тренируются больше всего?",["В симуляторе","Только на соревнованиях","Только на улице"],"В симуляторе можно летать сколько угодно без поломок."],["Кто побеждает в гонке?",["Кто быстрее прошёл трассу по правилам","У кого самый дорогой дрон","Кто взлетел выше всех"],"Нужно быстро и по правилам пройти всю трассу."],["Зачем нужна квалификация?",["Отобрать лучших по времени","Проверить, заряжены ли АКБ","Познакомить зрителей с пилотами"],"По лучшему времени выбирают, кто летит дальше."],["Почему в заезде мало пилотов, часто 4?",["Каждому нужен свой видеоканал","Пятеро не поместятся на старте","Так решают зрители"],"Каждому нужен свой видеоканал, а хорошо разнесённых каналов немного."],["Зачем перед гонкой тренировочные круги?",["Изучить трассу","Разрядить АКБ до хранения","Показать дрон зрителям"],"Пилот изучает трассу: где ворота, где повороты."],["Почему на гонке точность важна не меньше скорости?",["Авария стоит дороже аккуратного поворота","Скорость на гонке не считают","За точность дают отдельный кубок"],"Удар о ворота стоит больше времени, чем аккуратный поворот, а может закончить заезд."]],"x":[["Рамка, сквозь которую пролетают на трассе, - это...",["Ворота","Флаг","Старт"],"Сквозь ворота пролетают."],["Что на трассе облетают, а не пролетают насквозь?",["Флаг","Ворота","Финиш"],"Флаг облетают с нужной стороны."],["Сколько пилотов обычно летит в одном заезде?",["Несколько, часто 4","Всегда один","Все сразу, сколько пришло"],"Несколько, часто 4."],["Что идёт после квалификации?",["Заезды лучших и финал","Снова тренировка","Гонка заканчивается"],"Лучшие летят дальше, до финала."]]}]},"m5_class":{"t":"Классы гонок","sub":"С чего начинают и куда растут","e":"📏","pts":20,"steps":[{"s":"cards","h":"От вупа до пятидюймовика","cards":[{"h":"Старт: вупы 65-75 мм","p":"Почти все начинают с маленьких вупов, как наш Mobula 7: 75 мм, одна банка (1S), винты в защите. На них летают в зале и даже проводят настоящие вуп-гонки.","pic":"mob"},{"h":"Дальше: 2-3 дюйма","p":"Следующий шаг - дроны побольше, с винтами 2-3 дюйма. Они быстрее и сильнее вупа, им нужна площадка побольше.","pic":"e:🛩"},{"h":"Главный класс: 5 дюймов","p":"Большие гонки летают на 5-дюймовых дронах. Они разгоняются быстрее 100 км/ч. Это серьёзная техника для опытных пилотов, летают на ней только на огороженной трассе.","pic":"e:🏎"},{"h":"Что такое класс","p":"Класс - это правила, какие дроны летают вместе. В одном заезде дроны одного класса: так сравнивают пилотов, а не дроны.","pic":"e:⚖️"},{"h":"Путь гонщика","p":"Сначала симулятор, потом вуп в зале, потом дроны побольше. Следующий шаг - когда тренер видит, что ты уверенно летаешь на прежнем.","pic":"chain:Симулятор>Вуп 75 мм>3 дюйма>5 дюймов"}]},{"s":"game","h":"Тренажёр: вуп или пятидюймовик?","g":"sort","tip":"вуп маленький, лёгкий, в защите и летает в зале; пятидюймовик быстрый, тяжёлый и летает на огороженной трассе.","cats":["Вуп 65-75 мм","5 дюймов"],"items":[["Летает в зале клуба",0,"Вуп лёгкий и в защите - для зала."],["Наш Mobula 7",0,"Mobula 7 - вуп 75 мм."],["Винты в защитных кольцах",0,"Кольца вокруг винтов - примета вупа."],["Скорость больше 100 км/ч",1,"Так летают пятидюймовики."],["Летает на одной банке (1S)",0,"Вупу хватает одной банки."],["Гонки на огороженной трассе с сеткой",1,"Большому быстрому дрону нужна огороженная трасса."],["Первый гоночный дрон новичка",0,"С вупа начинают почти все."],["АКБ 4S или 6S",1,"Пятидюймовику нужно много банок."],["Главный класс больших гонок",1,"Большие гонки летают на 5 дюймах."],["Удар о ворота почти безопасен",0,"Вуп лёгкий, винты в защите."]]},{"s":"quiz","h":"Проверь себя","n":5,"pool":[["С какого дрона начинают гонщики в нашем клубе?",["С вупа Mobula 7","С пятидюймовика","С большого дрона для съёмки"],"Mobula 7 - маленький вуп в защите, на нём безопасно учиться."],["Какой размер у Mobula 7?",["75 мм","5 дюймов","75 см"],"75 мм между осями моторов по диагонали."],["Где летают вупы?",["В зале","Только на улице с сеткой","Только над стадионом"],"Лёгкий дрон в защите - для зала."],["Какой класс главный на больших гонках?",["5 дюймов","75 мм","2 дюйма"],"Большие гонки летают на 5-дюймовых дронах."],["Почему новички не начинают с пятидюймовика?",["Он быстрый и тяжёлый, ошибка опасна","Он слишком медленный для учёбы","У него нет камеры"],"Он быстрый и тяжёлый, ошибка новичка на нём опасна."],["Сколько банок в АКБ Mobula 7?",["Одна (1S)","Четыре (4S)","Шесть (6S)"],"Mobula 7 летает на одной банке - 1S."],["Что значит \"класс\" в гонках?",["Правила, какие дроны летают вместе","Год обучения пилота","Цвет рамы дрона"],"Класс - правила, какие дроны могут лететь вместе."],["Почему в одном заезде летят дроны одного класса?",["Чтобы сравнивать пилотов, а не технику","Чтобы было меньше шума","Чтобы судье было легче смотреть"],"Так сравнивают пилотов, а не технику."],["Какая АКБ обычно у гоночного пятидюймовика?",["4S или 6S","1S","Он работает от провода"],"Пятидюймовики летают на 4S или 6S."],["Когда можно переходить на дрон побольше?",["Когда тренер видит уверенный полёт","Сразу после первого занятия","Когда купил новый дрон"],"Решение за тренером: когда он видит уверенный полёт на прежнем дроне."]],"x":[["Mobula 7 относится к классу...",["Вупов 65-75 мм","Пятидюймовиков","Больших съёмочных дронов"],"Это вуп 75 мм."],["Какой дрон быстрее?",["Пятидюймовик","Mobula 7","Одинаково"],"Пятидюймовик разгоняется больше 100 км/ч."],["Что у вупа защищает винты?",["Кольца вокруг винтов","Чехлы на моторах","Сетка над дроном"],"Кольца вокруг винтов."],["Путь гонщика по порядку?",["Симулятор - вуп - 5 дюймов","5 дюймов - вуп - симулятор","Вуп - 5 дюймов - симулятор"],"Симулятор, потом вуп, потом дроны побольше."]]}]},"m5_fly1":{"t":"Полёт: разные трассы","sub":"Квадросим или Ворон: чистые круги на незнакомых трассах","e":"🎮","pts":15,"fly":true,"steps":[{"s":"cards","h":"Задание","cards":[{"h":"Летим в симуляторе","p":"Выбери в Квадросиме или Вороне две разные трассы. На каждой пролети 3 круга, проходя все ворота по порядку. Запиши лучшее время круга на второй трассе.","pic":"sim"},{"h":"О чём думать","p":"На новой трассе первый круг - разведка: медленно, смотри, где ворота и куда поворот. Пропустил ворота - вернись и пролети их, как требуют правила многих гонок. Чистый круг важнее быстрого: скорость придёт сама.","pic":"e:🗺"}]},{"s":"fly","h":"Впиши результат","sims":["Квадросим","Ворон"]}]},"m5_rules":{"t":"Правила гонки","sub":"Ворота, флаги, старт, фальстарт и зачёт","e":"🚦","pts":20,"steps":[{"s":"cards","h":"Как летают по правилам","cards":[{"h":"Ворота и флаги","p":"Трасса - это ворота и флаги. Сквозь ворота пролетаем, флаг облетаем с нужной стороны. Порядок задан заранее, срезать нельзя.","pic":"e:🚪🚩"},{"h":"Старт","p":"Дроны стоят на линии старта. Судья говорит: \"Арм!\" - пилоты включают моторы. Потом звучит сигнал, и только тогда - газ.","pic":"chain:На старт>\"Арм!\">Сигнал>Газ"},{"h":"Фальстарт","p":"Взлетел раньше сигнала - это фальстарт. Обычно заезд останавливают и начинают заново, а пилоту делают замечание или штраф.","pic":"e:🚫"},{"h":"Зачёт","p":"Зачёт - это как считают результат. Например: кто первым пролетел 3 круга. Или: у кого лучшее время круга. Как будут считать, судья говорит перед гонкой.","pic":"e:⏱"},{"h":"Упал на трассе","p":"Упал - сразу дизарм и громко скажи \"Упал!\", чтобы судья знал. На трассу за дроном не идём, пока заезд не кончился и судья не разрешил: другие ещё летят.","pic":"e:💥"}]},{"s":"game","h":"Тренажёр: по правилам","g":"order","sets":[{"q":"Старт заезда","items":["Поставить дрон на линию старта","Встать на место пилота","По команде судьи - арм","Дождаться сигнала","Взлететь"],"why":"Арм только с места пилота и по команде, газ - только после сигнала."},{"q":"Дрон упал на трассе","items":["Дизарм","Громко сказать \"Упал!\"","Ждать конца заезда","Забрать дрон, когда разрешит судья"],"why":"Сначала моторы, потом предупредить, а на трассу - только с разрешения."},{"q":"Пропустил ворота","items":["Заметить, что ворота пропущены","Развернуться","Пролететь пропущенные ворота","Лететь дальше по трассе"],"why":"Так требуют правила многих гонок: иначе круг не засчитают."},{"q":"Как проходит гонка","items":["Тренировочные круги","Квалификация","Заезды лучших","Финал"],"why":"Сначала изучаем трассу, потом отбор, потом решающие заезды."}]},{"s":"quiz","h":"Проверь себя","n":5,"pool":[["Ты облетел флаг не с той стороны. Это...",["Ошибка прохождения трассы","Можно, если так быстрее","Бонус за смелость"],"Флаг облетают с заданной стороны, иначе трасса пройдена неправильно."],["Что такое фальстарт?",["Взлёт раньше сигнала старта","Слишком медленный старт","Посадка после финиша"],"Фальстарт - взлёт раньше сигнала."],["Когда на старте можно дать газ?",["После сигнала старта","Сразу после арма","Когда взлетел сосед"],"Газ - только после сигнала старта."],["Дрон упал на трассе. Первое действие?",["Дизарм","Бежать за дроном","Взлетать на полном газу"],"Сначала дизарм, моторы должны стоять."],["Можно ли выйти на трассу за дроном во время заезда?",["Нет, ждём разрешения судьи","Да, если быстро","Да, если дрон близко"],"Другие ещё летят. Ждём конца заезда и разрешения судьи."],["Кто объявляет, как будут считать результат?",["Судья перед гонкой","Самый быстрый пилот","Зрители после финала"],"Правила зачёта судья объявляет перед гонкой."],["Зачем сигнал старта часто звучит через случайную паузу?",["Чтобы его нельзя было угадать","Чтобы зрители успели сесть","Чтобы АКБ успела прогреться"],"Чтобы сигнал нельзя было угадать и стартовать заранее."],["Ты пропустил ворота. Что делать по правилам многих гонок?",["Вернуться и пролететь их","Лететь дальше, никто не заметит","Сразу сесть"],"Нужно вернуться и пролететь их, иначе круг не засчитают."],["Зачёт: \"кто первым пролетит 3 круга\". Кто победил?",["Кто первым закончил 3 круга","Кто сделал самый быстрый круг","Кто дольше всех пролетал"],"Побеждает первый на финише после трёх кругов."],["Почему армят только по команде судьи?",["Судья видит, что трасса пуста и все на местах","Так меньше разряжается АКБ","Так быстрее начинается заезд"],"Судья видит, что все пилоты на местах, а на трассе никого нет."]],"x":[["Взлетел до сигнала старта - это...",["Фальстарт","Победа","Хороший старт"],"Это фальстарт."],["Флаг на трассе...",["Облетают с нужной стороны","Пролетают насквозь","Сбивают дроном"],"Флаг облетают с нужной стороны."],["Судья сказал \"Арм!\". Что ты делаешь?",["Включаю моторы и жду сигнала","Сразу взлетаю","Иду к дрону"],"Включаешь моторы и ждёшь сигнала."],["Зачем упавший пилот говорит \"Упал!\"?",["Чтобы судья знал, что дрон упал","Чтобы заезд перезапустили","Чтобы ему помогли взлететь"],"Судья должен знать, что дрон лежит на трассе."]]}]},"m5_video":{"t":"Видеоканалы на гонке","sub":"У каждого пилота свой","e":"📻","pts":20,"steps":[{"s":"cards","h":"Эфир на всех один","cards":[{"h":"Каждому - свой канал","p":"На гонке в воздухе сразу несколько дронов, и каждый шлёт картинку. Если двое на одном канале, у обоих в очках каша. Поэтому каждому пилоту дают свой канал.","pic":"e:📻"},{"h":"Подальше друг от друга","p":"Соседние каналы тоже немного мешают друг другу. Поэтому пилотам в заезде дают каналы подальше, например через один.","pic":"e:↔️"},{"h":"Канал назначает судья","p":"Перед заездом судья говорит каждому его канал. Пилот ставит этот канал на дроне и в очках и проверяет картинку. Сам менять канал во время гонки нельзя.","pic":"e:📋"},{"h":"В чужой заезд - не включаем","p":"Пока летит другой заезд, свой дрон не включаем. Его видеопередатчик может перебить картинку у летящего пилота, и тот разобьётся.","pic":"e:🔌"},{"h":"Мощность","p":"У нас слабый передатчик, около 25 mW - в зале этого хватает. Чем больше мощность, тем сильнее мешаешь соседям, поэтому сами её не прибавляем: какую ставить, решает тренер.","pic":"e:📶"}]},{"s":"game","h":"Тренажёр: можно или нельзя?","g":"sort","tip":"нельзя всё, что может перебить чужую картинку: чужой канал, соседний канал, включение во время чужого заезда, лишняя мощность.","cats":["Можно","Нельзя"],"items":[["Поставить канал, который назвал судья",0,"Верно: судья разводит каналы так, чтобы никто не мешал."],["Взять канал соседа, потому что он \"счастливый\"",1,"Два дрона на одном канале - каша в очках у обоих."],["Подключить АКБ, пока летит чужой заезд",1,"Твой передатчик может перебить чужую картинку."],["Проверить картинку в очках перед стартом",0,"Верно: так видно, что канал твой и всё работает."],["Включить дрон, когда вызвали твой заезд",0,"Верно: теперь в воздухе твой канал."],["Поменять канал прямо во время заезда",1,"Можно попасть на чужой канал и сбить другого пилота."],["Самому прибавить мощность передатчика",1,"Мощность решает тренер: сильный сигнал мешает соседям."],["Поставить одинаковый канал на дроне и в очках",0,"Верно: очки ловят только свой канал."],["Самому выбрать канал рядом с чужим",1,"Соседние каналы тоже мешают, их разводит судья."],["Сказать судье, что в очках чужая картинка",0,"Верно: судья разберётся с каналами."]]},{"s":"quiz","h":"Проверь себя","n":5,"pool":[["Двое пилотов заезда на одном канале. Что будет?",["У обоих в очках каша","Дроны полетят быстрее","Ничего, это не важно"],"Картинки смешаются, оба полетят вслепую."],["Кто назначает видеоканал на гонке?",["Судья","Каждый пилот сам","Зрители"],"Канал каждому пилоту назначает судья."],["Летит чужой заезд. Можно подключить АКБ к своему дрону?",["Нет, мой передатчик помешает","Да, если не взлетать","Да, если дрон в рюкзаке"],"Нельзя: твой передатчик может перебить чужую картинку."],["Кто у нас решает, какую мощность видео ставить?",["Тренер","Каждый пилот сам","Самый старший ученик"],"Передатчик слабый, около 25 mW. Какую мощность ставить, решает тренер."],["Что проверить в очках перед стартом?",["Что видна картинка моего дрона","Что очки чистые снаружи","Время на часах"],"Нужно видеть картинку именно со своего дрона."],["Канал на дроне и в очках должен быть...",["Одинаковым","Разным","Любым"],"Очки ловят только тот канал, на который настроены."],["Почему каналы в заезде берут подальше друг от друга?",["Соседние каналы тоже мешают","Так дальше летит сигнал","Так громче пищит таймер"],"Соседние каналы тоже немного мешают друг другу."],["Что такое Raceband?",["Группа гоночных каналов R1-R8","Название гоночных очков","Тип антенны"],"Это группа гоночных каналов R1-R8 с равными промежутками."],["Чем плох слишком мощный передатчик на гонке?",["Мешает другим пилотам","Ничем, так только лучше","Дрон от него тяжелеет"],"Сильный сигнал забивает каналы соседей."],["В полёте в очках вдруг появилась чужая картинка. Что делаешь?",["Дизарм и говорю судье","Лечу по чужой картинке","Сам меняю канал в полёте"],"Без своей картинки пилот летит вслепую: сразу дизарм, потом говорим судье."]],"x":[["Сосед хочет взять твой канал. Что скажешь?",["Нельзя, у обоих пропадёт картинка","Можно, если дроны одинаковые","Можно, если он сосед"],"На одном канале картинки смешаются у обоих."],["Когда на гонке подключаем АКБ к дрону?",["Когда вызвали мой заезд","Пока летят другие","Сразу, как пришёл"],"Только когда вызвали твой заезд."],["Хочешь сигнал посильнее. Как правильно?",["Спрошу тренера","Сам прибавлю","Сниму антенну"],"Мощность выставляет тренер."],["R1 и R2 в одном заезде - это хорошо?",["Не лучший выбор, они соседние","Отлично, они рядом","Не важно"],"Соседние каналы сильнее мешают друг другу, лучше взять подальше."]]}]},"m5_roles":{"t":"Роли на гонке","sub":"Пилот, споттер и судья","e":"🧑‍⚖️","pts":20,"steps":[{"s":"cards","h":"У каждого своё дело","cards":[{"h":"Пилот","p":"Пилот в очках ведёт дрон по трассе. Он слушает судью и споттера и выполняет команды сразу.","pic":"ochki2"},{"h":"Споттер","p":"Споттер стоит рядом с пилотом и смотрит на дрон своими глазами. Говорит коротко: \"Упал за флагом!\", \"Стоп, человек!\".","pic":"e:👀"},{"h":"Судья","p":"Судья главный на гонке. Он даёт старт, следит за воротами и фальстартами, считает круги. Команда судьи \"Дизарм!\" - значит дизарм всем. На наших занятиях судья - тренер.","pic":"e:🧑‍⚖️"},{"h":"Остальные","p":"Зрители стоят за сеткой. Пилоты следующего заезда готовят дроны, но не включают их. На гонке у каждого своё дело, и все вместе отвечают за безопасность.","pic":"e:🧍"}]},{"s":"game","h":"Тренажёр: чья это работа?","g":"sort","tip":"пилот ведёт дрон, споттер смотрит на дрон рядом с пилотом и подсказывает словами, судья командует и считает.","cats":["Пилот","Споттер","Судья"],"items":[["Ведёт дрон по трассе",0,"Это работа пилота."],["Даёт сигнал старта",2,"Старт даёт судья."],["Стоит рядом с пилотом и смотрит на его дрон",1,"Это споттер - глаза пилота снаружи."],["Говорит пилоту, где упал его дрон",1,"Пилот в очках может не понять, где дрон, - подсказывает споттер."],["Считает круги",2,"Круги считает судья."],["Армит дрон по команде",0,"Армит свой дрон пилот."],["Решает, был ли фальстарт",2,"Это решает судья."],["Летает в очках",0,"В очках - пилот."],["Смотрит, все ли ворота пройдены",2,"Это судьи на трассе."],["Подсказывает только словами, пульт не трогает",1,"Так работает споттер."],["Объявляет каналы пилотам",2,"Каналы разводит судья."]]},{"s":"quiz","h":"Проверь себя","n":5,"pool":[["Кто даёт старт заезду?",["Судья","Споттер","Самый быстрый пилот"],"Старт даёт судья."],["Что делает споттер?",["Смотрит на дрон и подсказывает пилоту","Ведёт дрон вместо пилота","Считает, сколько пришло зрителей"],"Он смотрит на дрон своими глазами и подсказывает пилоту."],["Судья сказал \"Дизарм!\". Что делает пилот?",["Сразу дизарм","Долетает круг","Спрашивает, зачем"],"Команду судьи выполняют сразу."],["Кто судья на наших занятиях?",["Тренер","Любой ученик","Никто"],"На занятиях судья - тренер."],["Зачем пилоту на гонке споттер?",["Пилот видит только картинку с камеры","Чтобы держать АКБ","Чтобы судья не скучал"],"Пилот видит только картинку с камеры, а не то, что вокруг."],["Что делают пилоты следующего заезда, пока летят другие?",["Готовят дроны, но не включают","Включают дроны заранее","Выходят на трассу посмотреть"],"Готовят дроны, но не включают: передатчик помешает летящим."],["Как споттер должен подсказывать?",["Коротко и спокойно, словами","Трогая пилота за руку","Громко и без остановки"],"Коротко, спокойно и только словами."],["Кто решает, засчитан ли круг?",["Судьи","Сам пилот","Споттер пилота"],"Судьи смотрят ворота и время."],["Друг-пилот спорит с судьёй прямо в полёте. Это...",["Ошибка: спорят после заезда","Правильно, так он защищает себя","Так и надо, чтобы выиграть"],"Команды судьи выполняют сразу, обсуждают после заезда."],["Что делает судья на трассе?",["Смотрит, все ли ворота пройдены","Ведёт дрон за пилота","Меняет пилоту канал в полёте"],"Он смотрит, все ли ворота пройдены."]],"x":[["Кто ведёт дрон по трассе?",["Пилот","Судья","Споттер"],"Дрон ведёт пилот."],["Кто на гонке считает круги?",["Судья","Споттер","Зрители"],"Круги считает судья."],["Может споттер взять пульт пилота?",["Нет, только подсказывает словами","Да, если пилот медленный","Да, на поворотах"],"Нет, споттер подсказывает только словами."],["Чьё слово главное на гонке?",["Судьи","Самого быстрого пилота","Зрителей"],"Главный на гонке - судья."]]}]},"m5_fly2":{"t":"Полёт: мини-заезд в зале","sub":"Mobula 7 с тренером: старт по сигналу, ворота по порядку","e":"🚁","pts":20,"fly":true,"steps":[{"s":"cards","h":"Задание","cards":[{"h":"Летим вживую","p":"На занятии с тренером: поставь Mobula 7 на линию старта, проверь свой канал. Арм - по команде, взлёт - только после сигнала. Пролети 2 круга по воротам в зале и сядь. Запиши время.","pic":"mob"},{"h":"Как на настоящей гонке","p":"Канал - твой, его назвал тренер. \"Арм!\" - включил моторы и ждёшь. Сигнал - плавный газ, не рывок. Ударился о ворота - дизарм и \"Упал!\". Рядом споттер, зрители за сеткой.","pic":"chain:Канал>Арм>Сигнал>Газ"}]},{"s":"fly","h":"Впиши результат","live":true},{"s":"coach","h":"Тренер принимает","p":"Тренер видел: свой канал, арм по команде, старт без фальстарта, ворота по порядку, посадка и дизарм."}]},"m5_rep":{"t":"Повторение: гонка Коли","sub":"Безопасность, устройство, АКБ и стики - с другой стороны","e":"🔁","pts":20,"steps":[{"s":"game","h":"Найди ошибки Коли","g":"story","tip":"вспомни включение дрона в чужой заезд, режимы полёта, вольты на посадку и правило \"к заармленному не подходим\".","story":[["Перед заездом Коля проверил, что АКБ не вздута и заряжена.",0,"Верно, это предполётная проверка."],["Пока летел чужой заезд, Коля подключил АКБ \"проверить картинку\".",1,"Пока летит чужой заезд, дрон не включаем: передатчик перебьёт чужую картинку."],["Коля поставил тот канал, который назвал судья.",0,"Верно, канал назначает судья."],["На старте Коля включил режим Acro, хотя тренировался только в Angle.",1,"На гонке летим в том режиме, в котором уверенно тренировался. В Acro дрон сам не выравнивается."],["По сигналу Коля плавно дал газ левым стиком.",0,"Верно: в Mode 2 газ - левый стик, и плавно."],["В очках было 3,4 В на банку, но Коля решил пролететь ещё два круга.",1,"Около 3,5 В на банку - пора садиться."],["Дрон врезался в ворота, и Коля сразу сделал дизарм.",0,"Верно, после удара - дизарм."],["Коля побежал на трассу за дроном, пока другие ещё летели.",1,"На трассу - только после заезда и с разрешения судьи."],["После заезда Коля дал горячей АКБ остыть и только потом поставил на зарядку.",0,"Верно, горячую АКБ сразу не заряжаем."],["Потом Коля снял очки и посмотрел вдаль, чтобы глаза отдохнули.",0,"Верно, глазам нужен отдых."]]},{"s":"quiz","h":"Вспомни модули 1-4 по-новому","n":5,"pool":[["Ты споттер у друга. Его дрон упал, моторы гудят. Что говоришь?",["\"Упал, дизарм!\"","\"Взлетай скорее!\"","Ничего, это его дело"],"Пилот должен сразу сделать дизарм."],["Перед стартом в очках 3,5 В на банку. Летишь заезд?",["Нет, меняю на заряженную АКБ","Да, заезд же короткий","Да, если лететь быстро"],"Это уже уровень посадки - нужна заряженная АКБ."],["Каким стиком в Mode 2 даёшь газ на старте?",["Левым, от себя","Правым, от себя","Правым, вбок"],"В Mode 2 газ - левый стик от себя."],["Зачем вупу на гонке защита винтов?",["Удар о ворота почти безопасен","С ней дрон летит быстрее","Без неё не работает камера"],"С защитой удар о ворота почти безопасен - и для дрона, и для всего вокруг."],["Друг хочет лететь заезд в незнакомом режиме Acro \"для скорости\". Это...",["Ошибка: лететь надо в привычном режиме","Хорошая идея","Не важно, режимы одинаковые"],"На гонке летят в том режиме, где уверенно тренировались."],["Чем Angle отличается от Acro?",["В Angle дрон выравнивается сам, в Acro - пилот","Ничем, это одно и то же","В Acro дрон выравнивается сам"],"В Angle дрон сам выравнивается по акселерометру, в Acro держит наклон, а выравнивает пилот."],["Какая деталь шлёт сигнал, по которому таймер узнаёт пилота?",["Видеопередатчик","Приёмник","Регулятор"],"Таймер ловит сигнал видеопередатчика."],["АКБ после заезда горячая, а через 10 минут снова твой заезд. Как правильно?",["Лечу на другой заряженной АКБ","Сразу ставлю горячую на зарядку","Охлаждаю её в морозилке"],"Горячую АКБ сразу не заряжают - летим на другой, заряженной."],["В заезде пропала связь с пультом. Что сделает настроенный failsafe?",["Выключит моторы, дрон упадёт","Вернёт дрон на старт","Пролетит трассу сам"],"Выключит моторы, дрон упадёт на месте."]],"x":[["Ты пилот, споттер крикнул \"Стоп, человек!\". Действие?",["Дизарм","Облетаю его","Лечу дальше"],"Человек рядом - сразу дизарм."],["При скольких вольтах на банку пора садиться?",["Около 3,5 В","Около 4,2 В","Около 3,8 В"],"Около 3,5 В на банку в спокойном полёте."],["Дрон сел после заезда. Что делаем по порядку?",["Дизарм - отключить АКБ - взять дрон","Взять дрон - дизарм","Выключить пульт - взять дрон"],"Дизарм, отключить АКБ, потом брать дрон."],["В каком режиме дрон держит наклон, пока пилот сам его не выровняет?",["Acro","Angle","Horizon"],"Это Acro."]]}]},"m5_coach":{"t":"На занятии: мини-гонка и викторина","sub":"Все роли на гонке и \"кто быстрее\" в группе MAX","e":"🧑‍🏫","pts":20,"steps":[{"s":"cards","h":"Что будет","cards":[{"h":"Побудь в каждой роли","p":"На занятии устроим мини-гонку на Mobula 7. Ты по очереди побудешь пилотом, споттером и помощником судьи: смотришь, все ли ворота пройдены, и считаешь круги. Главный судья - тренер.","pic":"e:🧑‍⚖️"},{"h":"Викторина \"кто быстрее\" в MAX","p":"Тренер проведёт викторину в группе клуба в MAX. Он пишет вопрос про гонки, а кто первым ответит правильно - получает балл. Когда начало и какие правила, тренер напишет в группе.","pic":"e:💬"},{"h":"Как подготовиться","p":"Перечитай карточки модуля: классы, правила, каналы, роли. Быстро отвечает тот, кто понимает, а не угадывает.","pic":"e:💡"}]},{"s":"coach","h":"Тренер принимает","p":"На занятии: побыл пилотом, споттером и помощником судьи на мини-гонке; поучаствовал в викторине \"кто быстрее\" в группе MAX. Тренер принимает."}]},"m5_final":{"t":"Итог модуля","sub":"Финальная проверка и заезд по правилам","e":"🎓","pts":30,"final":true,"steps":[{"s":"quiz","h":"Финальный тест: 10 вопросов","n":10,"pass":0.8,"from":["m5_class","m5_rules","m5_video","m5_roles"],"xall":1},{"s":"coach","h":"Заезд по правилам","p":"На занятии: пролетел заезд на Mobula 7 по правилам гонки: канал от судьи, арм по команде, старт без фальстарта, все ворота по порядку, после финиша - посадка, дизарм и отключить АКБ. Тренер принимает."}]},"m6_track":{"t":"Сложные трассы на время","sub":"Траектория, взгляд вперёд и газ в повороте","e":"⏱","pts":25,"steps":[{"s":"cards","h":"Как летает ас","cards":[{"h":"Сначала чисто, потом быстро","p":"Зачётная трасса - это ворота, флаги и повороты, которые надо пройти по порядку как можно быстрее. Считается время круга. Одна авария съедает больше секунд, чем аккуратный поворот. Поэтому правило аса: сначала чисто, потом быстро.","pic":"sim"},{"h":"Поворот - это дуга","p":"Поворот проходим плавной дугой: заходим с внешнего края, ближе всего проходим у внутренней стойки, выходим снова к внешнему краю. Так дуга получается широкой, и скорость почти не теряется.","pic":"e:↪️"},{"h":"Смотри на следующие ворота","p":"Пока пролетаешь ворота, взгляд уже на следующих. Тогда поворот начинаешь вовремя, а не когда стойка уже перед носом. Как на велосипеде: смотришь туда, куда хочешь ехать, и руки сами ведут туда.","pic":"e:👀"},{"h":"Газ в повороте","p":"Когда дрон наклоняется, часть тяги уходит вбок. Чтобы не терять высоту в повороте, газ чуть прибавляем. Отпустил газ в повороте - дрон \"проваливается\" вниз.","pic":"quad"},{"h":"Элементы трассы","p":"Змейка (слалом) - облетаем флаги по очереди то слева, то справа. Ныряние - пролетаем ворота на снижении, сверху вниз. Двойные ворота - две рамки подряд. В змейке легко раскачаться, в нырянии - слишком сильно спуститься к полу.","pic":"e:🐍"}]},{"s":"game","h":"Тренажёр: по порядку","g":"order","sets":[{"q":"Проходим поворот плавной дугой","items":["Зайти с внешнего края","Пройти ближе всего к внутренней стойке","Выйти к внешнему краю","Разогнаться на прямой"],"why":"Широкая дуга: снаружи - внутрь - наружу."},{"q":"Учим новую трассу","items":["Пролететь медленно и запомнить порядок ворот","Пролететь 3 круга без аварий","Понемногу ускоряться на знакомых участках","Ставить зачётное время"],"why":"Сначала чисто, потом быстро."},{"q":"Зачётный заезд в симуляторе","items":["Выбрать трассу","Сделать разминочный круг","Пролететь зачётные круги","Записать лучшее время круга"],"why":"Разминка перед зачётом - руки и глаза привыкают к трассе."},{"q":"Дрон в повороте проваливается вниз","items":["Заметить, где теряется высота","Понять причину: крен большой, газа мало","В этом повороте чуть добавить газ","Проверить на следующем круге"],"why":"Сначала причина, потом исправление и проверка."}]},{"s":"quiz","h":"Проверь себя","n":5,"pool":[["Главное правило зачётной трассы?",["Сначала чисто, потом быстро","Сразу полный газ на всей трассе","Быстро только на первом круге"],"Авария стоит больше секунд, чем аккуратный поворот."],["Куда смотреть, когда пролетаешь ворота?",["На следующие ворота","На ворота, в которых сейчас","На таймер в углу"],"Взгляд уже на следующих воротах - поворот начнёшь вовремя."],["Как лучше пройти поворот?",["Плавной дугой: снаружи, у стойки, наружу","Прямо до стойки и резко вбок","Вдоль внешнего края весь поворот"],"Плавная дуга: с внешнего края, ближе к стойке, снова наружу."],["Дрон наклонился в повороте и пошёл вниз. Что поможет?",["Чуть прибавить газ в повороте","Совсем убрать газ","Сильнее наклонить дрон"],"В наклоне часть тяги уходит вбок, поэтому газ чуть прибавляем."],["Новая трасса. С чего начать?",["С медленного круга, запомнить ворота","С самого быстрого круга","С зачёта без разминки"],"Сначала медленный круг, чтобы запомнить порядок ворот."],["Что такое змейка (слалом)?",["Облёт флагов то слева, то справа","Полёт по кругу у одних ворот","Пролёт двух ворот подряд"],"Флаги облетают по очереди то слева, то справа."],["Что значит \"медленно вошёл - быстро вышел\"?",["Тормозим до поворота, разгоняемся на выходе","Входим в поворот на полном газу","Тормозим только после поворота"],"Скорость сбрасывают до поворота, чтобы на выходе уже разгоняться."],["Что такое апекс поворота?",["Точка дуги ближе всего к внутренней стороне","Самая высокая точка трассы","Последние ворота перед финишем"],"Апекс - точка дуги, ближайшая к внутренней стороне поворота."],["Почему в крене дрон теряет высоту?",["Вверх идёт только часть тяги","В крене выключаются два мотора","В крене АКБ отдаёт меньше тока"],"Тяга направлена туда, куда наклонён дрон: вверх идёт только её часть."],["Как пройти ворота-ныряние?",["Убрать газ до ворот, добавить сразу после","Пройти на полном газу","Убрать газ после ворот"],"Газ убираем заранее, а сразу после ворот добавляем, чтобы не удариться о пол."]],"x":[["Ты пролетаешь ворота. Где твой взгляд?",["Уже на следующих воротах","На стойке рядом с дроном","На полу под дроном"],"Взгляд уже на следующих воротах."],["Что важнее всего на первой попытке новой трассы?",["Пролететь без аварий","Сразу побить рекорд","Пролететь на полном газу"],"Сначала чистые круги без аварий."],["В повороте дрон проседает. Что с газом?",["Чуть прибавить","Убрать до нуля","Не трогать совсем"],"В крене газ чуть прибавляют."],["Поворот лучше пройти...",["Плавной дугой","Углом с остановкой","Целиком по внешнему краю"],"Плавная дуга почти не теряет скорость."],["Где тормозим перед крутым поворотом?",["До поворота","В середине поворота","После выхода"],"Тормозим до поворота, чтобы выйти быстро."]]}]},"m6_fly1":{"t":"Полёт: сложная трасса на время","sub":"Квадросим или Ворон: чистые круги, потом скорость","e":"🎮","pts":15,"fly":true,"steps":[{"s":"cards","h":"Задание","cards":[{"h":"Летим в симуляторе","p":"Выбери в Квадросиме или Вороне трассу с поворотами и воротами. Сначала один медленный круг, чтобы запомнить ворота. Потом пролети 3 круга подряд без аварий. Запиши лучшее время круга.","pic":"sim"},{"h":"О чём думать","p":"Каждый круг - по одной и той же линии. Взгляд на следующие ворота, в повороте чуть газа. Упал - не злись: спокойно начни круг заново. Ровные круги важнее одного рекорда.","pic":"e:🎯"}]},{"s":"fly","h":"Впиши результат","sims":["Квадросим","Ворон"]}]},"m6_dvr":{"t":"Разбор ошибок по записи полёта","sub":"Смотрим повтор, ищем причину, выбираем упражнение","e":"📼","pts":25,"steps":[{"s":"cards","h":"Повтор, как в футболе","cards":[{"h":"Запись полёта","p":"Многие очки умеют записывать то, что видит пилот. Это называют DVR (видеозапись). В симуляторе можно записать экран. Запись - как повтор в футболе: можно посмотреть ещё раз и понять, что случилось.","pic":"e:📼"},{"h":"Причина - раньше аварии","p":"Авария - это конец ошибки, а не её начало. Отмотай запись на 1-2 секунды назад. Там видно, где ты поздно начал поворот или отпустил газ.","pic":"e:⏪"},{"h":"Что видно на записи","p":"Картинка резко дёргается - резкие движения стиков. Дрон проваливается вниз в повороте - мало газа в крене. Ворота внезапно выросли перед носом - поздно начал поворот. Картинка качается влево-вправо - слишком сильные поправки.","pic":"e:🔍"},{"h":"Одна ошибка - одно упражнение","p":"Выбери одну главную ошибку. Придумай упражнение именно на неё: например, 10 раз пройти этот поворот. Потом снова запиши полёт и сравни. Исправить всё сразу не получится, а одну ошибку за тренировку - вполне.","pic":"chain:Запись>Причина>Упражнение>Проверка"},{"h":"Цифры на записи","p":"В углу записи видны вольты и таймер. По ним видно, на какой минуте ты начал ошибаться. Часто ошибок больше в конце, когда устал или АКБ уже слабее.","pic":"osd"}]},{"s":"game","h":"Тренажёр: что видно - в чём причина","g":"match","pairs":[["Картинка резко дёргается","резкие движения стиков"],["В повороте дрон проваливается вниз","в крене мало газа"],["Ворота внезапно выросли перед носом","поздно начал поворот"],["Картинка качается влево-вправо","слишком сильные поправки"],["Дрон задел верх ворот","летел выше проёма"],["На записи пропала картинка, шум","проблема с видео: канал или антенна"]]},{"s":"quiz","h":"Проверь себя","n":5,"pool":[["Что такое DVR?",["Запись видео полёта","Режим полёта","Вид ворот на трассе"],"DVR - запись того, что пилот видит в очках."],["Где на записи искать причину аварии?",["За 1-2 секунды до удара","В сам момент удара","После посадки"],"Причина обычно за 1-2 секунды до удара."],["Картинка на записи резко дёргается. Почему?",["Резкие движения стиков","Слишком плавный газ","Новые винты"],"Дёрганая картинка - это резкие движения стиков."],["Сколько ошибок исправлять за одну тренировку?",["Одну главную","Все сразу","Ни одной, просто летать"],"Одну главную: тогда видно, помогло ли упражнение."],["Зачем смотреть запись своего полёта?",["Понять, где и почему ошибся","Только чтобы показать друзьям","Чтобы проверить заряд пульта"],"Со стороны видно, где и почему ты ошибся."],["На записи ворота появляются у самого носа, и ты бьёшься о стойку. Что исправить?",["Раньше начинать поворот","Лететь выше","Добавить газа на прямой"],"Начинать поворот раньше и смотреть на следующие ворота."],["Первые круги чистые, а в конце полёта много ошибок. Что проверить?",["Усталость и вольты АКБ в конце полёта","Цвет ворот","Номер видеоканала"],"В конце устают руки и глаза, а АКБ слабее и сильнее проседает."],["Зачем снова записать полёт после упражнения?",["Сравнить, исправилась ли ошибка","Чтобы заполнить память очков","Так требует симулятор"],"Сравнить записи и увидеть, исправилась ли ошибка."],["Картинка качается влево-вправо всё сильнее. Что это?",["Слишком сильные поправки - раскачка","Мало заряда в очках","Слишком слабые поправки"],"Каждая поправка слишком сильная, дрон проскакивает и раскачивается."]],"x":[["Что общего у DVR и повтора в футболе?",["Можно посмотреть момент ещё раз","Оба делают игру быстрее","Ничего общего"],"Оба позволяют посмотреть момент ещё раз."],["На записи дрон в повороте проваливается вниз. Причина?",["Мало газа в крене","Слишком много газа на прямой","Чужой видеоканал"],"В крене газа не хватило."],["Ты нашёл главную ошибку. Что дальше?",["Упражнение именно на эту ошибку","Сразу зачётный заезд","Забыть о ней"],"Упражнение именно на эту ошибку."],["Авария на записи - это...",["Конец ошибки, причина была раньше","Начало ошибки","Случайность без причины"],"Конец ошибки: причина была раньше."],["На записи дрон задевает верх ворот. Причина?",["Летел выше проёма ворот","Мало заряда в пульте","Слишком плавный поворот"],"Дрон летел выше проёма ворот."]]}]},"m6_fix":{"t":"Тренировка как у аса","sub":"Разминка, цель, отдых и спокойная голова","e":"🧠","pts":20,"steps":[{"s":"cards","h":"Привычки аса","cards":[{"h":"Разминка","p":"Перед зачётом - 1-2 спокойных круга. Руки привыкают к стикам, глаза - к трассе. Спортсмены тоже не бегут стометровку без разминки.","pic":"e:🔥"},{"h":"Одна цель на тренировку","p":"Цель должна быть понятной: \"пройти змейку 10 раз без касаний\". Не \"стать лучше во всём\". Маленькие цели легко проверить, и каждая тренировка что-то даёт.","pic":"e:🎯"},{"h":"Упал - спокойно","p":"Авария - это подсказка, что тренировать. Злость мешает: руки становятся резкими, и ошибок больше. Выдохни, начни круг заново аккуратно.","pic":"e:😤"},{"h":"Отдых","p":"После каждого полёта снимай очки и смотри вдаль. Устал - перерыв. Уставший пилот летает хуже, и никакая тренировка этого не исправит.","pic":"e:😌"},{"h":"Новое - только на тренировке","p":"Новый трюк или новую линию сначала пробуем на тренировке много раз. На зачёте летаем так, как уже умеем.","pic":"e:🆕"}]},{"s":"game","h":"Тренажёр: привычка аса или ошибка?","g":"sort","tip":"ас готовится, ставит одну цель, летит плавно и спокойно, а новое пробует только на тренировке.","cats":["Привычка аса","Ошибка"],"items":[["Разминочный круг перед зачётом",0,"Руки и глаза привыкают к трассе."],["После аварии разозлиться и лететь ещё быстрее",1,"Злость делает руки резкими - ошибок больше."],["Смотреть на следующие ворота",0,"Так поворот начинается вовремя."],["Летать час без перерыва, не снимая очков",1,"Глазам и рукам нужен отдых."],["Плавные движения стиков",0,"Плавно - точно и быстро."],["Резко дёргать стики в каждом повороте",1,"Рывки дают раскачку и аварии."],["Цель на тренировку: один трудный поворот",0,"Одна понятная цель - видно результат."],["Пробовать новый трюк прямо на зачёте",1,"Новое сначала отрабатывают на тренировке."],["Сесть, когда в очках 3,5 В на банку",0,"Пора садиться - АКБ бережём."]]},{"s":"quiz","h":"Проверь себя","n":5,"pool":[["Зачем разминочный круг перед зачётом?",["Руки и глаза привыкают к трассе","Чтобы разрядить АКБ","Чтобы запомнить время соседа"],"Руки привыкают к стикам, глаза - к трассе."],["Ты упал на трассе. Что дальше?",["Успокоиться и следующий круг лететь аккуратно","Сразу лететь на полном газу","Закончить тренировку на сегодня"],"Выдохнуть и следующий круг пролететь аккуратно."],["Глаза устали в очках. Что делать?",["Снять очки и отдохнуть","Летать дальше","Прибавить яркость в очках"],"Снять очки, посмотреть вдаль, отдохнуть."],["Какая цель на тренировку лучше?",["Пройти трудный поворот 10 раз чисто","Стать лучше во всём сразу","Летать, пока не надоест"],"Одна понятная цель, которую легко проверить."],["Ошибка на тренировке - это...",["Подсказка, что тренировать","Повод бросить полёты","Всегда вина симулятора"],"Ошибка подсказывает, что тренировать дальше."],["Почему на зачёте летят чуть медленнее своего максимума?",["Остаётся запас на ошибку - меньше аварий","Так требуют правила гонки","Медленный круг всегда быстрее"],"Небольшой запас скорости - это запас на ошибку."],["Почему новый трюк не пробуют на зачёте?",["Новое сначала отрабатывают на тренировке","Трюки запрещены всегда","Трюк не засчитают во время круга"],"Новое сначала отрабатывают на тренировке, пока не станет привычным."],["Что лучше для навыка пилота?",["Понемногу, но регулярно","Редко, но по много часов","Только перед самой гонкой"],"Регулярные короткие тренировки закрепляют навык лучше редких длинных."]],"x":[["Перед зачётом ас сначала делает...",["Разминочный круг","Сразу зачётный круг","Новый трюк"],"Разминочный круг."],["После аварии ас...",["Спокойно летит дальше аккуратно","Злится и разгоняется","Ругает дрон"],"Спокойно продолжает и летит аккуратно."],["Какая привычка помогает летать чисто?",["Плавные движения стиков","Резкие рывки газа","Полёт без перерывов час"],"Плавные стики - точный полёт."],["Цель на тренировку должна быть...",["Одна и понятная","Сразу про всё","Не нужна вовсе"],"Одна и понятная."],["Ты летишь на пределе и часто падаешь. Совет?",["Чуть сбавить и летать чисто","Лететь ещё быстрее","Взять трассу сложнее"],"Чуть сбавить скорость и пролетать круги чисто."]]}]},"m6_fly2":{"t":"Полёт: зачётная трасса в зале","sub":"Mobula 7 с тренером: ворота на время","e":"🚁","pts":25,"fly":true,"steps":[{"s":"cards","h":"Задание","cards":[{"h":"Летим вживую","p":"На занятии тренер ставит в зале трассу из нескольких ворот. С наблюдателем рядом пролети её на Mobula 7: 3 круга без касаний ворот. Садись при 3,5 В на банку и впиши напряжение при посадке.","pic":"mob"},{"h":"Правила не отменяются","p":"Тренер разрешил, зрители за сеткой, наблюдатель рядом. Перед стартом громко: \"Взлетаю!\", перед посадкой: \"Сажусь!\". Упал или что-то не так - сразу дизарм. Быстро - потом, сначала безопасно.","pic":"e:🛡"}]},{"s":"fly","h":"Впиши результат","live":true},{"s":"coach","h":"Тренер принимает","p":"Тренер видел зачётные круги: безопасный старт, полёт без касаний, посадка вовремя и дизарм."}]},"m6_day":{"t":"Зачётный день: найди ошибки","sub":"История Димы на трассе на время","e":"📖","pts":15,"steps":[{"s":"game","h":"Найди ошибки Димы","g":"story","tip":"вспомни про взгляд вперёд, газ в повороте, спокойствие после аварии и разбор записи.","story":[["Перед зачётом Дима сделал медленный разминочный круг.",0,"Верно, руки и глаза привыкают к трассе."],["В повороте он смотрел на стойку, мимо которой летел.",1,"Смотрим уже на следующие ворота."],["Перед крутым поворотом Дима заранее сбросил скорость.",0,"Верно: медленно вошёл - быстро вышел."],["В крене он совсем убрал газ, и дрон провалился к полу.",1,"В крене газ чуть прибавляют."],["После аварии Дима разозлился и полетел ещё быстрее.",1,"После аварии - пауза и аккуратный круг."],["Он включил запись в очках, чтобы потом разобрать полёт.",0,"Верно, запись помогает найти ошибки."],["На зачёте Дима впервые в жизни попробовал split-S.",1,"Новое сначала отрабатывают на тренировке."],["Разбирая запись, он отмотал на 2 секунды до удара.",0,"Верно, причина раньше аварии."],["Дима решил исправить за одну тренировку сразу пять ошибок.",1,"Одна ошибка - одно упражнение."],["Когда в очках стало 3,5 В на банку, он сказал \"Сажусь!\" и сел.",0,"Верно, пора садиться."]]},{"s":"quiz","h":"Коротко о главном","n":3,"pool":[["Какая ошибка Димы стоила ему высоты в повороте?",["Убрал газ в крене","Сделал разминку","Включил запись"],"В крене газ убирать нельзя - дрон проваливается."],["Что Дима сделал правильно?",["Включил запись полёта","Смотрел на ближнюю стойку","Полетел быстрее после аварии"],"Запись помогает разобрать полёт."],["Что Диме делать после аварии?",["Успокоиться и лететь аккуратно","Лететь ещё быстрее","Пробовать новый трюк"],"Пауза и спокойный, аккуратный круг."],["Почему split-S на зачёте - ошибка, если Дима его не тренировал?",["Непривычный элемент легко сорвать - будет авария","Split-S запрещён в симуляторе","Split-S всегда медленнее"],"Непривычный элемент легко срывается - это авария и потерянное время."]],"x":[["Куда Диме надо было смотреть в повороте?",["На следующие ворота","На ближнюю стойку","На пол"],"На следующие ворота."],["Что делать с газом в крене, чтобы дрон не провалился?",["Чуть прибавить","Убрать совсем","Резко дать полный"],"В крене газ чуть прибавляют."],["Где на записи Дима нашёл причину аварии?",["За 1-2 секунды до удара","В момент удара","После посадки"],"За 1-2 секунды до удара."],["Сколько ошибок Диме исправлять за тренировку?",["Одну главную","Все пять","Ни одной"],"Одну главную."]]}]},"m6_as":{"t":"Тест \"Ас\"","sub":"Стики, режимы полёта и лётные навыки","e":"🏆","pts":25,"steps":[{"s":"cards","h":"Перед тестом","cards":[{"h":"Кто такой ас","p":"Ас - пилот, который летает быстро, чисто и безопасно. Он знает свой пульт и режимы полёта, следит за АКБ и разбирает свои ошибки. Этот тест - про всё, чему ты научился как пилот.","pic":"e:🏆"},{"h":"Вспомни режимы","p":"Angle: отпустил стик - дрон сам выровнялся. Acro: дрон держит наклон, который ты задал, выравнивает пилот. Horizon - между ними.","pic":"e:🕹"}]},{"s":"quiz","h":"Тест \"Ас\"","n":5,"pool":[["В каком режиме дрон сам выравнивается, если отпустить стик?",["Angle","Acro","Ни в каком"],"В Angle контроллер сам возвращает дрон в ровное положение."],["В Mode 2 газ - это какой стик?",["Левый, вверх-вниз","Правый, вверх-вниз","Левый, влево-вправо"],"Газ - левый стик вверх-вниз."],["Ты отпустил правый стик в Acro. Что делает дрон?",["Держит тот наклон, что был","Сам выравнивается","Выключает моторы"],"В Acro дрон держит тот наклон, что был, выравнивает пилот."],["Левый стик влево. Что делает дрон?",["Поворачивается на месте","Летит влево","Снижается"],"Это рыскание: поворот на месте."],["Правый стик от себя в Angle. Что делает дрон?",["Наклоняется и летит вперёд","Поднимается вверх","Поворачивается на месте"],"Дрон наклоняется носом вниз и летит вперёд."],["Ас - это пилот, который...",["Летает быстро, чисто и безопасно","Летает быстро, даже если падает","Летает только в симуляторе"],"Быстро - мало. Ас летает ещё и чисто, и безопасно."],["Почему опытные гонщики летают в Acro?",["Точное управление и можно переворачиваться","В Acro дрон сам облетает ворота","В Acro АКБ садится медленнее"],"Дрон делает ровно то, что задал пилот: точнее, и можно делать перевороты."],["Что такое режим Horizon?",["Смесь Angle и Acro","Режим посадки","Режим записи видео"],"Смесь: у центра стика выравнивается, при полном отклонении может перевернуться."],["В повороте в Acro пилот отпустил стик крена. Что будет?",["Дрон останется в наклоне и уйдёт вбок","Дрон сам выровняется","Дрон замрёт на месте"],"Дрон останется в наклоне и продолжит уходить вбок."],["В каком режиме новичку лучше начинать в зале?",["Angle","Acro","Horizon с полным отклонением"],"В Angle дрон выравнивается сам - проще удержать."]],"x":[["Отпустил стик - дрон выровнялся. Какой режим?",["Angle","Acro","Режим записи"],"Это Angle."],["Отпустил стик - дрон так и летит в наклоне. Какой режим?",["Acro","Angle","Режим посадки"],"Это Acro."],["Какой стик в Mode 2 наклоняет дрон вперёд?",["Правый от себя","Левый от себя","Левый вбок"],"Правый стик от себя."],["Поворот на месте в Mode 2 делает...",["Левый стик вбок","Правый стик вбок","Тумблер арма"],"Левый стик вбок - рыскание."],["Horizon ведёт себя как Angle, когда...",["Стик около центра","Стик до упора","Дрон стоит на земле"],"Стик около центра - дрон выравнивается."]]}]},"m6_rep":{"t":"Повторение: весь курс","sub":"История Ани и вопросы с другой стороны","e":"🔁","pts":20,"steps":[{"s":"game","h":"Найди ошибки Ани","g":"story","tip":"вспомни порядок включения, свой канал, зарядку LiPo, проверку винтов, старт по сигналу и горячую АКБ.","story":[["Аня включила пульт, потом очки и только потом подключила АКБ.",0,"Верно: пульт - очки - АКБ."],["Перед гонкой она взяла канал соседа, потому что на нём картинка ярче.",1,"У каждого пилота свой канал, иначе картинки мешают друг другу."],["Обычную LiPo Аня зарядила в режиме LiHV, \"чтобы полетать подольше\".",1,"Обычную LiPo заряжаем только до 4,2 В, в режиме LiPo."],["Она попросила Олю быть наблюдателем.",0,"Верно, наблюдатель видит дрон и людей вокруг."],["В зале Аня поставила мощность видео 25 mW, как сказал тренер.",0,"Верно, в зале хватает 25 mW."],["Перед стартом она не посмотрела, целые ли винты.",1,"Винты проверяем перед каждым полётом."],["Аня стартовала раньше сигнала судьи.",1,"Это фальстарт: стартуем только по сигналу."],["Когда пропало видео, она сразу сделала дизарм.",0,"Верно, без видео - сразу дизарм."],["После полёта Аня сразу поставила горячую АКБ на зарядку.",1,"Сначала АКБ должна остыть."],["Перед неделей без полётов она перевела АКБ в хранение, около 3,8 В на банку.",0,"Верно, так АКБ живёт дольше."]]},{"s":"quiz","h":"Вспомни модули 1-5 по-новому","n":5,"pool":[["Ты судья, а пилот стартовал раньше сигнала. Как это называется?",["Фальстарт","Круг почёта","Дизарм"],"Старт до сигнала - фальстарт."],["Друг говорит: \"Чтобы дрон поднялся, двигаю правый стик\". Что ты поправишь?",["Газ - левый стик от себя","Всё верно","Газ - правый стик вбок"],"В Mode 2 газ - левый стик вверх-вниз."],["Ты помогаешь новичку. У него в очках 3,5 В на банку, а он хочет ещё круг. Что скажешь?",["Садись, пора на посадку","Лети, заряда ещё много","Лети, но на полном газу"],"3,5 В на банку - сигнал садиться."],["На каком дроне в клубе делают первые гонки?",["Mobula 7: 75 мм, винты в защите","Большой пятидюймовый","Любой большой с камерой"],"Mobula 7: 75 мм, винты в защите - безопасно для зала."],["У соседа пропала картинка, а дрон слушается пульта. Какая система подвела?",["Видео","Управление","Полёт"],"Картинку дают камера, видеопередатчик и антенна - это видео."],["Гонщик в очках. Кто рядом следит за дроном и людьми?",["Наблюдатель (споттер)","Сам пилот","Никто, это не нужно"],"Наблюдатель (споттер) видит то, чего не видит пилот."],["Двое пилотов видят рябь, хотя антенны целые. Что проверить первым?",["Не совпали ли их видеоканалы","Заряд пультов","Винты"],"Частая причина - одинаковые видеоканалы."],["Ты хочешь поставить в дрон для 4S АКБ 6S \"для скорости\". Что скажешь себе?",["Нельзя: может сгореть электроника","Можно, будет быстрее","Можно, если летать недолго"],"Ставим только АКБ с тем числом банок, на которое рассчитан дрон."],["Ты перешёл с Angle на Acro и отпустил стик в наклоне. Почему дрон не выровнялся?",["В Acro выравнивает сам пилот","Сломался гироскоп","Села АКБ"],"В Acro дрон держит угол, выравнивает пилот."]],"x":[["Пилот стартовал раньше сигнала. Это...",["Фальстарт","Финиш","Разминка"],"Это фальстарт."],["Кто на занятии разрешает старт?",["Тренер или судья","Зрители","Любой пилот"],"Тренер или судья."],["АКБ горячая после полёта. Что сначала?",["Дать остыть","Сразу на зарядку","Положить в морозилку"],"Дать ей остыть."],["Газ в Mode 2 - это...",["Левый стик вверх-вниз","Правый стик вбок","Правый стик вверх-вниз"],"Левый стик вверх-вниз."],["Какой мощности видео хватает в зале?",["25 mW","600 mW","Самой большой"],"В зале хватает 25 mW."]]}]},"m6_coach":{"t":"На занятии: разбор с тренером","sub":"Запись, одна ошибка, упражнение","e":"🧑‍🏫","pts":20,"steps":[{"s":"cards","h":"Что будет на занятии","cards":[{"h":"Принеси запись","p":"Запиши свой полёт: в очках (DVR) или запись экрана симулятора. Вместе с тренером найдите одну главную ошибку и момент за 1-2 секунды до неё.","pic":"e:📼"},{"h":"Расскажи и покажи","p":"Скажи своими словами: что видно на записи, в чём причина и какое упражнение поможет. Потом покажи на Mobula 7 в зале поворот плавной дугой - с наблюдателем и по всем правилам.","pic":"e:🗣"}]},{"s":"coach","h":"Тренер принимает","p":"На занятии: разобрал с тренером запись своего полёта, назвал главную ошибку, её причину и упражнение. Показал на Mobula 7 поворот плавной дугой. Тренер принимает."}]},"m6_final":{"t":"Итог курса: экзамен Аса","sub":"Финальная проверка по всему курсу и зачётный заезд","e":"🎓","pts":30,"final":true,"steps":[{"s":"quiz","h":"Финальный тест: 10 вопросов","n":10,"pass":0.8,"from":["m6_track","m6_dvr","m6_as","m6_rep"],"xall":1},{"s":"coach","h":"Зачётный заезд Аса","p":"На занятии: сделал предполётную проверку, включил всё по порядку, сказал \"Взлетаю!\", пролетел зачётную трассу на Mobula 7 без касаний с наблюдателем, сел вовремя, сделал дизарм и выключил всё по порядку. Назвал одну свою ошибку и как её исправить. Тренер принимает."}]}}};
